ITEM_ROLES = [('damage', 'Offense'), ('shieldmagic', 'Defense'), ('position', 'Mobility'), ('clock', 'Action economy'),
              ('arcane', 'Spellcasting'), ('utility', 'Utility')]
# name: dict(r=ratings, g=grade, cat=category, slot=slot, plan=(level, 'Core'|'Option'|'Situational') or None, band, ev)
I = {}


def i(n, r, g, cat, slot, plan, band, ev):
    I[n] = dict(r=r, g=g, cat=cat, slot=slot, plan=plan, band=band, ev=ev)


# ───────── Weapon property runes (Aspera) ─────────
i('Ghost Touch', '200003', 'C', 'Weapon rune', 'Weapon property', (4, 'Situational'), 'Levels 4–8',
  "Ghost Touch lets Aspera hit incorporeal creatures fully, which matters only if incorporeal enemies appear before Astral can be afforded at 8. Astral includes the same effect and adds damage, so Ghost Touch is worth buying only as a temporary measure when such enemies are known to be coming at low level.")
i('Fearsome', '410002', 'A', 'Weapon rune', 'Weapon property', (5, 'Core'), 'Levels 5–7, then 10+; greater from 12',
  "Fearsome makes every critical hit frighten the target, which lowers its AC, attacks and saves against everyone fighting it. Cyrus scores critical hits most often against off-guard targets, from flanking, Trip and invisibility, and when Sure Strike lets him roll twice, so it takes effect regularly in the fights where he arranges those advantages, and it is the best property rune available at 5. The greater version at 12 frightens 2, which keeps it worth a slot alongside a damage rune. It does nothing against creatures immune to fear, and it adds nothing if his allies are already keeping the target frightened. Aspera has only one property slot until +2 weapon potency at 10, so when Astral arrives at 8 Fearsome moves to a runestone and returns in the second slot at 10.")
i('Rooting', '230003', 'B', 'Weapon rune', 'Weapon property', (7, 'Option'), 'Levels 7+, major from 15',
  "Rooting immobilises the target for a round on a critical hit, with no saving throw, and makes it clumsy 1 while the roots hold. The target can Escape, but that costs it an action and counts as an attack for its multiple attack penalty, so even the cheapest version takes an action from any enemy, and the later versions only make the Escape harder. It works on creatures immune to fear, which Fearsome does not, and it keeps a mobile enemy, or one making for the spellcasters behind him, inside Aspera's reach. It adds nothing on ordinary hits. It is the rune that replaces Fearsome against enemies immune to fear, and the leading choice for a fourth slot at 18.")
i('Astral', '400004', 'A', 'Weapon rune', 'Weapon property', (8, 'Core'), 'Levels 8+, greater from 15',
  "Astral adds spirit damage to every hit and includes Ghost Touch, so one rune covers incorporeal enemies and adds damage the rest of the time. It is the best general rune at 8, and a critical hit can force a possessing spirit out of its host. Constructs and other creatures without a spirit ignore the extra damage, and against those Frost or Shock is the better rune.")
i('Frost', '300002', 'B', 'Weapon rune', 'Weapon property', (8, 'Option'), 'Levels 8+, greater from 15',
  "Frost adds cold damage to every hit, and a critical hit slows the target for a round if it fails a Fortitude save. The save DC is fixed and Fortitude is the strong save of most dangerous enemies, so it slows weaker enemies and almost never a strong one, against which it is simply a damage rune. Cold is resisted more often than electricity or acid and less often than fire. It is the energy rune to bring against a known weakness to cold.")
i('Flaming', '300002', 'B', 'Weapon rune', 'Weapon property', (8, 'Option'), 'Levels 8+, greater from 15',
  "Flaming adds fire damage to every hit and persistent fire on a critical hit, 2d10 in the greater version, which is the largest additional damage among the energy runes and allows no save. Fire is the most often resisted element, although the greater rune ignores resistance, if not immunity. It is the damage choice for a spare slot at high level and the rune to bring against a known weakness to fire.")
i('Shock', '300002', 'B', 'Weapon rune', 'Weapon property', (8, 'Option'), 'Levels 8+, greater from 15',
  "Shock adds electricity damage to every hit, and critical hits arc to two more creatures nearby. Electricity is resisted less often than fire or cold, which makes it the most dependable energy rune when no weakness is known, and the arc matters only when enemies stand close together.")
i('Cunning', '000202', 'C', 'Weapon rune', 'Weapon property', (5, 'Situational'), 'Levels 5+',
  "Once a minute, after Cyrus hits and damages a creature that has blood, Cunning lets him Recall Knowledge about it as a free action, with a bonus equal to Aspera's potency and +2 more after a critical hit. That lets him Recall Knowledge in the course of attacking without spending an action, but it needs one of Aspera's property slots, which are also wanted for Fearsome, Astral and the elemental runes, all of which add more to most fights, and it does nothing against bloodless creatures such as constructs and many undead.")
i('Wounding', '300002', 'C', 'Weapon rune', 'Weapon property', None, 'Levels 7+',
  "Wounding adds persistent bleed on every hit. Persistent damage of the same type doesn't stack, and many dangerous enemies resist or ignore bleed, so the elemental runes do more.")
i('Grievous', '220002', 'D', 'Weapon rune', 'Weapon property', None, 'Levels 9+',
  "Grievous improves critical specialisation effects, which Cyrus doesn't get from his class.")
i('Shifting', '000202', 'D', 'Weapon rune', 'Weapon property', None, 'Levels 6+',
  "Shifting turns Aspera into another weapon, but Cyrus relies on Aspera's own traits, so he has no reason to change its form.")

# ───────── Armour property runes ─────────
i('Mobile', '000430', 'B', 'Armour rune', 'Armour property', (5, 'Option'), 'Levels 5–7',
  "Mobile lets Cyrus Step 10 feet once a turn. For someone fighting with a reach weapon that is a real improvement, because he can step out from beside an enemy to 10 feet, or into a flanking square, without provoking the reactions that ordinary movement triggers. It is the best use of the armour's only slot from 5 to 7, after which Sunweave takes its place.")
i('Convincing', '000002', 'C', 'Armour rune', 'Armour property', (5, 'Situational'), 'Levels 5+, greater from 8, major from 16',
  "Convincing gives +1 to Diplomacy checks to Make an Impression and Request, +2 from the greater version at 8 and +3 from the major version at 16, without using an investment slot. It needs one of the armour's property slots, which Mobile, Sunweave and Fortification are due to fill, and the Shawl of Seasons already gives +2 to Make an Impression, so it is worth a slot only if social scenes come to matter more than those runes.")
i('Moonweave', '010002', 'C', 'Armour rune', 'Armour property', None, 'Levels 5+',
  "Moonweave adds a few Hit Points to each magical heal Cyrus receives. The early amounts are small, and repeated healing from the same effect only benefits once, so Mobile and Sunweave do more with the slot.")
i('Sunweave', '000304', 'A', 'Armour rune', 'Armour property', (7, 'Core'), 'Levels 7+, greater from 11',
  "Sunweave gives an item bonus to Perception and a daily fortune roll on initiative. Acting before the enemy lets Cyrus Trip it, change position or arrange a flank before it moves, and that is when his turns are worth most. It is the preferred general-purpose armour rune and stays in the first slot at every level after. The Perception bonus overlaps with other item bonuses such as Obsidian Goggles.")
i('Fortification', '050000', 'A', 'Armour rune', 'Armour property', (12, 'Core'), 'Levels 12+, greater from 18',
  "Fortification gives a chance to turn every critical hit against Cyrus into an ordinary hit. At high level it is critical hits that bring down those who fight at the front, so this is the strongest defensive rune for the second armour slot, which opens at 11. It adds 1 Bulk and raises the armour's Strength threshold by 1, so Lattice Armor needs Strength +4 instead of +3 to avoid its check and Speed penalties, which Cyrus's Strength should already meet by 12.")

# ───────── Spellhearts (attached to Aspera or the armour) ─────────
i('Clay Sphere', '410103', 'A', 'Spellheart', 'Attachment', (3, 'Core'), 'Levels 3–10, greater from 6',
  "Clay Sphere casts Gouging Claw from the item, which frees a cantrip slot. Casting a morph spell through it also gives Aspera all three physical damage types for a minute and raises its damage die by one step until the end of Cyrus's next turn, so the following Strikes hit harder and get past physical resistances. The greater version at 6 adds a daily Enlarge, which makes him Large and takes Aspera's reach to 15 feet for a fight. It is the best attachment for Aspera until the greater Phantasmal Doorknob at 10, when it can move to the armour's attachment slot. There it loses the weapon effect but still casts Gouging Claw and the daily Enlarge. That slot is also where Cyrus's best talismans go, so the move is only worth it if the daily Enlarge matters more than a Mortalis Coin or Emerald Grasshopper.")
i('Flaming Star', '300101', 'B', 'Spellheart', 'Attachment', (3, 'Option'), 'Levels 3–12',
  "Flaming Star casts Ignition from the item and adds fire damage to Aspera's Strikes until the end of Cyrus's next turn after a fire spell cast through it. The greater version adds a daily Fireball at the item's own DC. It is the leading alternative to Clay Sphere if Cyrus wants a source of fire damage, although fire is the most commonly resisted element.")
i('Jolt Coil', '300101', 'B', 'Spellheart', 'Attachment', (3, 'Option'), 'Levels 3–12',
  "Jolt Coil casts Electric Arc from the item and adds electricity damage to follow-up Strikes. The greater version adds a daily Lightning Bolt at the item's DC, which is useful if Cyrus has no dependable area spell against Reflex. The weapon effect applies only to a Strike made soon after the spell, and his turns do not always include one.")
i('Phantasmal Doorknob', '420002', 'A', 'Spellheart', 'Attachment', (6, 'Option'), 'Levels 6+, greater from 10',
  "Phantasmal Doorknob's value lies in the effect it adds to Aspera's critical hits, which needs no action. The standard version dazzles on a critical hit, which is modest. The greater version at 10 blinds the target until the end of its next turn on a critical hit, which forces flat checks on every attack it makes and leaves it off-guard. Because he so often attacks off-guard targets, he scores critical hits more often than his attack bonus alone would suggest, and blinding a powerful enemy for a round is worth a great deal when it happens, so this is the strongest attachment for Aspera from 10. A creature that has been blinded this way is immune for a day, so it works once on each enemy.")
i('Warding Statuette', '030102', 'C', 'Spellheart', 'Attachment', (7, 'Situational'), 'Levels 7+',
  "Warding Statuette gives a creature next to the target a small AC bonus when Cyrus hits. At 10-foot reach he is rarely next to his target, so the bonus usually goes to the ally in melee with it. That is a modest benefit to give an attachment slot to.")

# ───────── Worn and held items ─────────
i('Ancestral Geometry', '050012', 'A', 'Worn item', 'Invested', (3, 'Core'), 'Levels 2+',
  "Ancestral Geometry records the higher of two d20 rolls each morning, along with a random save type, and Cyrus can use that roll in place of one save of that type during the day. A high stored roll can turn a failed save against a dangerous effect into a success, and the tattoo also gives a Lore bonus that fits the Val'Dira family. Its limits are the random save type and the reaction it uses, but for its level it is excellent protection.")
i("Healer's Gloves", '040003', 'A', 'Worn item', 'Invested', (4, 'Core'), 'Levels 4+, greater from 9',
  "Healer's Gloves heal an adjacent ally for one action once a day, which gets a downed or nearly downed ally back into the fight without waiting for a healer. It is a manipulate activation, so Cyrus needs a hand free. The greater version at 9 heals enough to matter at higher levels.")
i('Kindler Cameo', '051002', 'A', 'Worn item', 'Invested, held', (7, 'Core'), 'Levels 7+',
  "Once a day, Kindler Cameo heals Cyrus by a large amount for its level, ends every persistent damage effect on him at once and gives a +2 status bonus to Will saves for a minute. Ending persistent damage on its own can save a fight against fire, acid or bleed. It is held in one hand to activate, so it goes well with a Retrieval Belt, which puts it in his hand as a free action. The healing doesn't scale, so it is strongest from 7 to the early teens, and still useful after a fight.")
i('Red Thread Knot', '050000', 'A', 'Worn item', 'Invested', (7, 'Option'), 'Levels 7+',
  "Red Thread Knot turns a critically failed save into a failure, as a reaction, up to six times in total. At high level a critically failed save is what most often removes a character from a fight, and the knot needs no hands. It uses Cyrus's reaction, which he also wants for Reactive Strike, and the six uses are finite, so it is best kept for saves where a critical failure would decide the fight.")
i('Shawl of Seasons', '000403', 'A', 'Worn item', 'Invested', (5, 'Core'), 'Levels 5+',
  "Set to spring, the shawl gives a +5-foot item bonus to Speed until the next preparations, which takes Cyrus to 40 feet in Arcane Cascade and extends Dimensional Assault. It also gives +2 to Make an Impression, which suits someone who relies on Diplomacy. Boots give the same kind of bonus to Speed, so it is replaced only when greater Boots of Bounding or Propulsive Boots arrive.")
i('Boots of Bounding', '000402', 'B', 'Worn item', 'Invested', (14, 'Option'), 'Levels 7+, greater from 14',
  "Boots of Bounding give an item bonus to Speed and better jumps. The standard version's +5 feet doesn't stack with the Shawl of Seasons, so it only matters if the shawl isn't worn. The greater version at 14 gives +10 feet, which is the larger land Speed of the two late footwear options.")
i('Propulsive Boots', '000542', 'A', 'Worn item', 'Invested', (13, 'Option'), 'Levels 13+',
  "Propulsive Boots give +5 feet of Speed and, once a day, a minute of quickened that can only be used to move. An extra action for movement in every turn of the day's main fight lets Cyrus reach a flanking square and still Spellstrike and recharge. Greater Boots of Bounding give more Speed at all times, but the daily minute of being quickened does more for his turns.")
i('Winged Sandals', '000402', 'C', 'Worn item', 'Invested', (10, 'Situational'), 'Levels 10+',
  "Winged Sandals give a 30-foot fly Speed for 10 minutes once a day and automatic fall protection. They are excellent on a day that involves a great deal of climbing and height, but for everyday wear the items that add land Speed are better.")
i('Obsidian Goggles', '010003', 'B', 'Worn item', 'Invested', (11, 'Core'), 'Levels 5+, greater from 11',
  "Cyrus is human, so he has no darkvision. The standard goggles give it for an hour a day, and the greater version at 11 gives it whenever he wants along with a larger Perception bonus. That bonus overlaps with Sunweave's, so the reason to buy the goggles is the vision, and the greater pair is well worth its price at 11.")
i('Echo Receptors', '210003', 'B', 'Worn item', 'Invested', (10, 'Situational'), 'Levels 10+',
  "Echo Receptors give precise hearing to 40 feet, which lets Cyrus pinpoint invisible enemies and ignore darkness within 40 feet. They deal with the problem well if darkness or invisibility keeps costing him turns. As a graft they alter his body, so the decision is about the character as much as about the benefit.")
i('Lifting Belt', '200102', 'C', 'Worn item', 'Invested', (4, 'Option'), 'Levels 4–8',
  "Lifting Belt gives +1 to Athletics. When Cyrus Trips with Aspera he already adds the weapon's potency bonus, so the belt only helps other Athletics checks such as Escape, climbing and Force Open. It is worn as a belt, so it cannot be worn with the Retrieval Belt.")
i('Armbands of Athleticism', '200103', 'C', 'Worn item', 'Invested', (9, 'Option'), 'Levels 9–10',
  "Armbands give +2 to Athletics and better climbing and swimming. Like the Lifting Belt, they don't add to Trips with Aspera once its potency bonus matches, so their value is in Athletics checks outside weapon Trips. They don't use the belt slot, which leaves it free for the Retrieval Belt.")
i("Mage's Hat", '000013', 'B', 'Worn item', 'Invested', (3, 'Option'), 'Levels 3+',
  "Mage's Hat gives +1 to Arcana and Prestidigitation. Arcana is Cyrus's main skill for Recall Knowledge and he is the one who identifies creatures and magic for his allies, so it is the most useful of the early skill items. The Master Magus Ring at 11 gives a larger Arcana bonus.")
i("Diplomat's Badge", '000003', 'B', 'Worn item', 'Invested', (5, 'Option'), 'Levels 5+',
  "Diplomat's Badge gives +1 to Diplomacy, rising to +2 with a group Cyrus identifies each day. The daily activation is a DC 20 Recall Knowledge check, usually with Society, and the group can be a human ethnicity or a whole non-human ancestry such as dwarves. When he does much of the talking, it is a good early skill item, though the check is only about 60% at 5 while Society is trained.")
i('Choker of Elocution', '000003', 'B', 'Worn item', 'Invested', (6, 'Option'), 'Levels 6+',
  "Choker of Elocution gives +1 to Society and fluency in a chosen language and its customs. It suits court and diplomatic scenes where a language barrier or a social mistake would be costly.")
i('Scholarly Journal', '000003', 'C', 'Held item', 'Held', (3, 'Situational'), 'Levels 3+',
  "A Scholarly Journal gives +1 to Recall Knowledge on one narrow subject after a minute of reading. A compendium covers a broader topic. It is an inexpensive preparation for a subject that is known to recur, such as one kind of creature or a particular city.")
i("Tactician's Helm", '000342', 'A', 'Worn item', 'Invested', (6, 'Core'), 'Levels 6+',
  "Tactician's Helm gives +1 to Warfare Lore, the skill Improvise Strategy rolls, and stores a charge each time Cyrus hits with Reactive Strike. Once an hour he spends a charge and one action to Stride twice, to Interact up to three times, or to gain a +2 status bonus to Athletics and Acrobatics for the turn. Two Strides for one action amounts to an extra action for a magus, who is always one short, and three Interacts in one action cover drawing a scroll or potion and taking hold of Aspera again. The status bonus adds to Trips made with Aspera, which use the weapon's potency as their item bonus. With a reach weapon he makes a Reactive Strike in most fights, and the helm holds two charges through the day, so a charge is usually in hand before the fight that needs it. It is the cheapest way to gain an action before Propulsive Boots.")
i('Retrieval Belt', '000503', 'A', 'Worn item', 'Invested', (7, 'Core'), 'Levels 7+, greater from 9',
  "Retrieval Belt puts a stored item into a free hand as a free action, which removes the action of drawing from the use of a scroll, a potion or the Kindler Cameo. Cyrus still has to take hold of Aspera again afterwards, but each use of an item costs one action fewer. The greater version at 9 holds three items, which lets him choose the right one for the fight. It is the main reason that scrolls and items for particular situations become practical for him.")
i('Ring of Wizardry', '000060', 'S', 'Worn item', 'Invested', (7, 'Core'), 'Type I 7, II 10, III 12, IV 14',
  "Ring of Wizardry adds arcane spell slots each day: two rank-1 slots for Type I, and at Types II, III and IV two slots of the next ranks up plus one below. Cyrus has two slots of each rank, so Type I doubles his rank-1 slots for Sure Strike and utility, and Type IV at 14 takes rank 4 from two slots to four and rank 3 from two to three. That gives him more spells for Spellstrike and room for defensive and other useful spells without giving up either. Only one such ring works in a day, and the slots are lost if it is removed.")
i('Endless Grimoire', '000050', 'A', 'Held item', 'Held during preparations', (6, 'Core'), '6, greater 10, major 14, true 18',
  "Endless Grimoire lets Cyrus prepare one extra spell each day, at rank 1, 3, 5 or 7 depending on the version, as long as he uses it during his preparations. It costs nothing in combat because it only needs to be held while preparing. Together with the Ring of Wizardry it adds four slots a day from level 10, about a third more than his own two per rank, which leaves room for spells of general use alongside his attack spells.")
i('Accolade Robe', '000003', 'C', 'Worn item', 'Invested', (10, 'Situational'), 'Levels 10+',
  "Accolade Robe gives +2 to Arcana and a one-action activation to pull an academic item from its pockets and Recall Knowledge. Its extra Focus Point can be spent only on wizard school spells, which Cyrus does not have. The Master Magus Ring gives the same Arcana bonus at 11 with far better activations.")

i('Pendant of the Occult', '100003', 'B', 'Worn item', 'Invested', (3, 'Option'), 'Levels 3+, greater from 9',
  "Pendant of the Occult gives +1 to Occultism, or +2 from the greater version at 9, and lets Cyrus cast Guidance as a cantrip at will, which gives an ally +1 to one check and frees a cantrip slot. Occultism covers aberrations, spirits, oozes and other occult creatures that Arcana and Society don't. While his Occultism remains trained, the cantrip is the main reason to wear it, and the greater version, which adds a daily Dream Message, is worth buying only if he raises Occultism to expert.")
i('Pristine Epaulets', '010002', 'B', 'Worn item', 'Invested', (5, 'Option'), 'Levels 5+',
  "Pristine Epaulets give +1 to Society and Warfare Lore, both skills Cyrus uses, and once a day let him reroll a critically failed Diplomacy check. Critical failures in negotiation are rare, but they are the result that sours a deal or turns a meeting hostile, so the reroll protects the scenes in which the most is at stake.")
i('Cloak of Social Graces', '220002', 'B', 'Worn item', 'Invested', (7, 'Option'), 'Levels 7+, greater from 13',
  "Cloak of Social Graces gives +1 to Diplomacy, or +2 from the greater version at 13, and once a day casts Heroism on Cyrus for a minute, at 6th rank from the greater version. A free Heroism is valuable when a divine caster's slots are needed elsewhere. The activation takes two actions, so it is best used just before a fight he can see coming. It is worn as a cloak, so it cannot be worn with the Cloak of Illusions, which is useful until 10.")
i("Messenger's Ring", '000102', 'B', 'Worn item', 'Invested', (9, 'Option'), 'Levels 9+',
  "Messenger's Ring gives +2 to Diplomacy, Message as an arcane innate spell at will and a daily Animal Messenger. Having Message at will frees a cantrip slot and lets him and his allies coordinate quietly. Only the highest item bonus to Diplomacy applies, so it overlaps with the Diplomat's Badge and Cloak of Social Graces, and Cyrus needs only one of the three at a time.")
i('Humbug Pocket', '000002', 'C', 'Worn item', 'Invested', (9, 'Situational'), 'Levels 9+',
  "Humbug Pocket gives +2 to Society and, once an hour, produces a forged document on demand that lasts an hour. Papers, passes and letters of introduction can open doors in towns and cities, but the need arises only now and then, so the Pristine Epaulets or the Choker of Elocution are the more reliable Society items.")
i('Thousand-Blade Thesis', '100202', 'C', 'Held item', 'Invested, held', (9, 'Situational'), 'Levels 9+',
  "Thousand-Blade Thesis gives +2 to Warfare Lore checks to Recall Knowledge while held in one hand, stores 5 Bulk of weapons, and once a day gives a minute in which Cyrus can draw stored weapons as a free action. Holding it means taking a hand off Aspera, so the Lore bonus is mainly for use outside combat. Its Instant Armory activation is worth having only if he carries several weapons worth changing to, such as cold iron or silver weapons for enemies with those weaknesses.")
i('Open Mind', '000303', 'A', 'Worn item', 'Invested', (10, 'Option'), 'Levels 10+',
  "Open Mind gives +1 to Lore checks and, once an hour for one action, the effects of Hypercognition: up to six Recall Knowledge actions at once. In a fight with several kinds of enemy, or against one creature with several things worth knowing, that is far more information than any other item gives for one action, so the most important question should come first. Free actions that are triggered by Recall Knowledge, such as Kreighton's Cognitive Crossover, cannot be used during it.")
i('Brooch of Inspiration', '000002', 'B', 'Worn item', 'Invested', (11, 'Situational'), 'Levels 8+, greater from 11',
  "Brooch of Inspiration gives +1 to Recall Knowledge with Lore skills, or +2 from the greater version at 11, and a two-action activation that rolls a Lore Recall Knowledge check twice, once a day or once an hour for the greater version. It helps only where Academia or Warfare Lore applies, such as armies, mercenary companies, battles, academies and arcane institutions, and two actions are a high price in a fight, so it is most useful outside combat. Its bonus is an item bonus, so it replaces the Lore bonuses from the Tactician's Helm, Open Mind and Thousand-Blade Thesis instead of adding to them.")
i('Master Magus Ring', '200450', 'S', 'Worn item', 'Invested', (11, 'Core'), 'Levels 11+',
  "Master Magus Ring is the best item made for his class. Once a day it gives a Focus Point for a conflux spell, which means one more Dimensional Assault or Dimensional Disappearance in the day's most important fight, and once a day it teleports Cyrus up to his Speed as a free action. The teleport can put him in reach without spending any of the actions he needs for Spellstrike and recharge. It also gives +2 to Arcana.")
i('Sash of Books', '340033', 'A', 'Worn item', 'Invested, apex', (17, 'Core'), 'Levels 17+',
  "Sash of Books is the apex item for Cyrus. In a fight against one strong enemy it does more than a Strength apex: one action gives +1 to hit that creature and +1 to AC and saves against it whatever he rolls, and +2 on a critical success, which two rolls with legendary Arcana make more likely than not against a creature of his level that Arcana identifies. The same check tells him which save to aim a spell at, so the action belongs on his first turn. The Intelligence raises his spell DC, and the daily Foresight costs no rank-9 slot.\n\nStrength would add 1 damage to each Strike, 1 to hit every creature he has not studied and 1 to Athletics, so Bracers of Strength are better against many equal enemies. The AC bonus does not add to Shield, and the sash takes the garment slot, which rules out an Accolade Robe.")
i('Bracers of Strength', '400003', 'A', 'Worn item', 'Invested, apex', (17, 'Option'), 'Levels 17+',
  "Bracers of Strength raise Strength, which improves the attack roll and damage of the Strike that carries every Spellstrike, and Athletics. They also give a large Athletics bonus. They are the Strength alternative to the Sash of Books. They are better over a fight against many enemies, because their bonus applies to every Strike, and worse against the one creature on which the sash is used.")
i('Crown of Intellect', '000044', 'A', 'Worn item', 'Invested, apex', (17, 'Option'), 'Levels 17+',
  "Crown of Intellect raises Intelligence, which improves spell DCs and every save spell Cyrus delivers through Spellstrike, plus a large bonus to Recall Knowledge and an hourly Hypercognition. It is the Intelligence apex item to take if the Sash of Books cannot be had, since it gives the same Intelligence and better Recall Knowledge, though without the bonuses against a studied creature or the daily Foresight.")

# ───────── Consumables ─────────
C = {}


def c(n, r, g, cat, ev):
    C[n] = dict(r=r, g=g, cat=cat, ev=ev)


c('Healing Potion', '040003', 'A', 'Healing and defence', "Keep one strong enough to survive the next hit. It heals at once, on Cyrus's own turn, without an ally's actions. Loaded in a Potion Patch it costs one action and both hands stay on Aspera; otherwise it costs a draw, the drink and a regrip.")
c('Potion Patch', '000503', 'S', 'Access and hands', "A loaded patch lets Cyrus drink the potion inside for one action without letting go of Aspera. That turns a healing potion or a Potion of Quickness from a three-action turn into a one-action turn. Only one patch works at a time, and its magic ends at the next daily preparations, so in practice it is one potion a day: usually the healing potion, or a Potion of Quickness before a planned fight. The lesser patch holds potions up to level 10, the moderate up to 15 and the greater any level.")
c('Retrieval Prism', '000403', 'B', 'Access and hands', "A Retrieval Prism puts one prepared item into a free hand as a free action. It does the Retrieval Belt's job for one item without using the belt slot or an investment, but it takes the armour's attachment slot.")
c("Cat's Eye Elixir", '300003', 'A', 'Weapon treatments', "Cat's Eye removes the flat check against concealed targets and lowers it against hidden ones within 30 feet. A Spellstrike that fails a flat check wastes the slot as well as the attack, so this protects his most expensive action against fog, blur and invisibility.")
c('Mistform Elixir', '040003', 'B', 'Healing and defence', "Mistform makes Cyrus concealed against targeted attacks. The moderate version lasts a minute and is the better dose to drink before a fight. It does nothing against area effects.")
c('Numbing Tonic', '040002', 'B', 'Healing and defence', "Numbing Tonic gives temporary Hit Points when drunk and again at the start of each of Cyrus's turns for a minute. It is an elixir, so it can't go in a Potion Patch; it is best drunk just before a fight against many attacks.")
c('Soothing Tonic', '030002', 'C', 'Healing and defence', "Soothing Tonic heals a little each round for a while. It suits recovery after a fight more than an emergency.")
c('Potion of Quickness', '000503', 'A', 'Healing and defence', "Potion of Quickness quickens Cyrus for a minute, giving an extra Strike or Stride each turn. In a Potion Patch it costs one action, which the extra action repays on the next turn, so in a long fight it is a large gain. It fits the basic patch's level limit.")
c('Transmuting Ingot', '400003', 'A', 'Weapon treatments', "A Transmuting Ingot makes Aspera count as a chosen material for a minute, which turns a known weakness to silver or cold iron into extra damage on every hit. Applying it costs an action, so use it before the fight or when Cyrus is out of reach.")
c('Potency Crystal', '200002', 'C', 'Weapon treatments', "A Potency Crystal gives temporary fundamental runes for one Strike. Aspera has its own runes, so it is only useful on the backup light hammer.")
c('Oil of Potency', '200002', 'C', 'Weapon treatments', "Oil of Potency gives a weapon temporary fundamental runes for a minute. It is a fallback for a backup weapon below the matching rune tier.")
c('Ghostbane Fulu', '300003', 'B', 'Weapon treatments', "Ghostbane Fulu activates after a hit and lets Aspera affect that particular incorporeal creature fully. It is affixed like a talisman, and Aspera can hold only one talisman or spellheart, so using it means removing the spellheart for that fight. It is a cheap answer to a known ghost before Astral.")
c('Escape Fulu', '040103', 'C', 'Movement', "Escape Fulu improves repeated Escape and Stealth checks for a minute. It is an armour talisman, so it takes the armour's attachment slot, and it is only worth affixing when a grappler is expected.")
c('Analysis Eye', '000003', 'C', 'Weapon treatments', "Analysis Eye reveals a weakness or resistance after a hit on several unfamiliar enemies. Magus's Analysis already covers most of this.")
c('Emerald Grasshopper', '000403', 'B', 'Movement', "Emerald Grasshopper is the clean combat jump with both hands on Aspera: one action for a 40-foot Leap. It solves gaps, ledges and rooftops that would otherwise stop a reach fighter. It is an armour talisman, so it shares the armour's single attachment slot with the Retrieval Prism, Mortalis Coin and any spellheart on the armour.")
c('Blast Boots', '000303', 'C', 'Movement', "Blast Boots power one planned big jump and still use the jump action. Emerald Grasshopper does the same with less setup.")
c('Gecko Pads', '000203', 'C', 'Movement', "Gecko Pads give a climb for a planned ascent. Gecko Grip covers the same need without the free-hand problem.")
c('Oil of Skating', '000202', 'C', 'Movement', "Oil of Skating speeds movement on smooth or downhill ground and struggles on anything else.")
c('Smoke Ball', '030203', 'C', 'Movement', "Smoke Ball conceals a cloud centred on Cyrus, which covers an escape. It also conceals enemies from the party, so warn allies first.")
c('Oil of Mending', '000002', 'C', 'Mission supplies', "Oil of Mending repairs a broken item. Bring one on expeditions where a broken tool or shield would matter.")
c('Energizing Tea', '200102', 'C', 'Mission supplies', "Energizing Tea gives an item bonus to a planned Athletics or Acrobatics challenge.")
c('Heartening Missive (Butterfly)', '000004', 'B', 'Mission supplies', "The butterfly Missive lets a known recipient improve one important Diplomacy or Performance check, provided it arrives in time. It can decide a negotiation.")
c('Bottled Lightning', '200102', 'C', 'Offense', "Bottled Lightning makes a target off-guard from range. It is better handed to an ally who is ready to throw it than thrown by Cyrus from a two-handed grip.")
c('Stumbling Fulu', '020002', 'C', 'Offense', "Stumbling Fulu needs access to the target's armour and has a fixed, low DC. It is a trick for an infiltration rather than a fight.")
c('Explosive Missive', '200002', 'C', 'Offense', "Explosive Missive is a planned burst delivered by messenger. Its fixed DC falls behind Cyrus's own spells.")
c('Blight Breath', '210002', 'C', 'Offense', "Blight Breath gives poison resistance while held and a short damaging cone. It is a niche pick for a poison-heavy enemy.")

# ───────── Additional permanent items (survey of the rules data) ─────────
# Weapon runes
i('Keen', '300001', 'C', 'Weapon rune', 'Weapon property', None, 'Levels 13+',
  "Keen makes a natural 19 a critical hit as long as it would have hit. That adds something only where a 19 is not a critical hit already, which means against an enemy well above his level when he has little help, and there it doubles his chance of a critical hit. Once the target is off-guard and frightened and he has a bonus of his own, a 19 is already a critical hit and Keen does nothing, and against weaker enemies it never matters. Its value falls as the help he gets from his allies improves, so a rune with an effect of its own is the better use of a slot.")
i('Ashen', '420002', 'A', 'Weapon rune', 'Weapon property', (16, 'Core'), 'Levels 9+, greater from 16',
  "Every hit with an Ashen weapon deals persistent fire damage and confuses the target for a round unless it succeeds at a Will save. It is the only effect rune that works on an ordinary hit, so it does not depend on critical hits or on help from his allies, and a confused enemy is off-guard, cannot use reactions and can only Strike at random. The save DC is fixed, 25 for the standard rune and 35 for the greater, so each version is strong for about two levels after it becomes available and weaker after that. Against an enemy two levels above him, the greater rune confuses on about one hit in five at 16 and one in twelve at 18. A confused creature can also try a DC 11 flat check to recover whenever an attack or spell damages it. The greater rune is Aspera's third rune at 16, and the standard one is an alternative to Fearsome at 10.")
i('Hooked', '320002', 'B', 'Weapon rune', 'Weapon property', (5, 'Option'), 'Levels 5+',
  "Because Aspera already has the trip trait, a Hooked rune lets Cyrus attempt a Trip as a reaction whenever he critically hits. A prone target is off-guard to him and to his allies and has to spend an action standing up, which can provoke his Reactive Strike. The Trip uses his multiple attack penalty if it happens on his own turn, so it is most reliable on a critical hit from his first attack. At 5 Aspera has only one property slot, and Fearsome is the better use of it, because frightening the target on every critical hit helps all his allies where Hooked gives only one more check.")
i('Impactful', '300002', 'B', 'Weapon rune', 'Weapon property', (10, 'Option'), 'Levels 10+, greater from 17',
  "Impactful adds 1d6 force damage to every hit. Force is rarely resisted, which makes it the most dependable of the plain damage runes, but its critical effect pushes the target 5 feet away, which is usually unhelpful to someone with a reach weapon who wants enemies to stay where he can hit them. It is a reasonable damage rune where Frost's cold is resisted.")
i('Brilliant', '310002', 'B', 'Weapon rune', 'Weapon property', (12, 'Option'), 'Levels 12+, greater from 18',
  "Brilliant adds 1d4 fire damage to every hit, plus 1d4 spirit damage against fiends and 1d4 vitality damage against undead, so against those enemies one rune delivers three damage types and can set off more than one weakness. A critical hit blinds the target for a round unless it succeeds at a Fortitude save, and its activation can end magical darkness within Aspera's reach. The standard rune's save DC is low by 16 and the greater version at 18 is expensive, so as a source of blindness it is weaker than the greater Phantasmal Doorknob, which allows no save. If the Doorknob is not on Aspera, Brilliant is the rune that restores a chance of blinding. It is a fair choice for a fourth slot for its range of damage types, and a strong one against fiends and undead.")
i('Corrosive', '300002', 'B', 'Weapon rune', 'Weapon property', (8, 'Option'), 'Levels 8+, greater from 15',
  "Corrosive adds 1d6 acid damage to every hit and damages the target's armour or raised shield on a critical hit. Acid is resisted less often than fire, so it is a dependable alternative to Frost, Flaming or Shock as a plain damage rune.")
i('Thundering', '300001', 'C', 'Weapon rune', 'Weapon property', (8, 'Option'), 'Levels 8+, greater from 15',
  "Thundering adds 1d6 sonic damage to every hit and can deafen the target on a critical hit. Deafened only matters against enemies that rely on auditory effects or verbal spellcasting checks, so the other damage runes have better critical effects.")
i('Nightmare', '310002', 'C', 'Weapon rune', 'Weapon property', None, 'Levels 9+',
  "Nightmare adds 1d6 mental damage, and a critical hit leaves the target stupefied 1, or frightened 2 as well if it was already stupefied. Mental damage and the fear effects are ignored by mindless creatures and by creatures immune to mental effects, so it falls behind Fearsome and Astral.")
i('Spell Reservoir', '300200', 'C', 'Weapon rune', 'Weapon property', None, 'Levels 13+',
  "Spell Reservoir stores one spell of rank 3 or lower, cast into the weapon over a minute, and releases it with a Strike for two actions; save spells use a fixed DC 30. In practice it gives Cyrus one extra Spellstrike-like attack per fight, such as a stored Slow, without spending his Spellstrike charge. It costs a property slot that Fearsome, Astral and Frost use every round, so it only fits if one of those is not needed.")
i('Quickstrike', '400300', 'C', 'Weapon rune', 'Weapon property', None, 'Levels 16+',
  "Quickstrike makes Cyrus permanently quickened, but the extra action can only be a Strike with Aspera. After a Spellstrike that Strike is at a −10 penalty, so it rarely hits. Hasted Assault at 14 already makes him quickened with an action usable for Stride or Strike, and quickened conditions don't add extra actions together, so the rune adds nothing on the turns he uses Hasted Assault.")
i('Vorpal', '400001', 'C', 'Weapon rune', 'Weapon property', None, 'Levels 17+',
  "Vorpal can decapitate a creature with a head on a natural 20 that critically hits and deals slashing damage, with a Fortitude save. It is an incapacitation effect, so it almost never works on the powerful enemies that matter at that level, and natural 20s are too rare to plan around.")
i('Bane', '300001', 'C', 'Weapon rune', 'Weapon property', (4, 'Situational'), 'Levels 4+',
  "Bane adds 1d6 damage against one creature type, such as fiends or dragons. It is worth a slot only when many enemies share that type, and the type is fixed when the rune is made.")

# Armour runes
i('Antimagic', '060000', 'A', 'Armour rune', 'Armour property', (18, 'Option'), 'Levels 15+',
  "Antimagic gives a +1 status bonus to saves against magic, and once a day it can try to counteract a spell that targets Cyrus or includes him in its area, as a rank-7 Dispel Magic with a +26 modifier. That reaction can stop a Disintegrate, a Dominate or a control spell outright, which matters most at the levels where a single failed save can take him out of a fight. It is the strongest choice for the third armour slot at 18. The reaction competes with Reactive Strike, but only once a day.")
i('Spellwatch', '050000', 'B', 'Armour rune', 'Armour property', (18, 'Option'), 'Levels 13+',
  "Spellwatch gives Cyrus a new saving throw against one hostile spell affecting him at the start of each of his turns, ending it on a success. It shortens slow, paralysis, confusion and similar control spells, and with master Will from level 9 those extra saves often succeed. It is the alternative to Antimagic for the third armour slot: Spellwatch helps after a spell lands, while Antimagic can stop it before it lands.")
i('Dread (Lesser)', '310000', 'B', 'Armour rune', 'Armour property', (12, 'Option'), 'Levels 6+, moderate from 12, greater from 18',
  "Dread makes frightened enemies within 30 feet that can see Cyrus attempt a Will save at the end of their turn, and on a failure their frightened value doesn't drop below 1. With Fearsome on Aspera and any ally who Demoralizes, it keeps the −1 to AC, attacks and saves on the enemy for several rounds instead of one. The lesser rune's DC 20 is low, so the rune becomes worthwhile with the moderate version at 12 (DC 29) and the greater at 18 (DC 38). It would take the second armour slot from Fortification or the third from Antimagic.")
i('Deathless', '040000', 'C', 'Armour rune', 'Armour property', None, 'Levels 7+',
  "Once a day Deathless reduces a new wounded or doomed condition by 1 as a reaction. That makes the next time Cyrus goes down less dangerous, which matters to someone who fights at the front. Before 11 the armour has one slot, and Sunweave helps in every fight, so Deathless is an option for later levels when a series of dangerous fights is expected.")
i('Size-Changing', '300100', 'C', 'Armour rune', 'Armour property', None, 'Levels 7+',
  "Size-Changing casts Enlarge or Shrink on Cyrus once a day for one action, which is cheaper than casting Enlarge. The greater Clay Sphere already provides a daily Enlarge, so this is only worth a slot if the Clay Sphere is not in use.")
i('Energy-Resistant', '040000', 'C', 'Armour rune', 'Armour property', (8, 'Situational'), 'Levels 8+, greater from 12',
  "Energy-Resistant gives resistance 5 to one energy type, or 10 with the greater rune. It is worth fitting when many enemies use one element, and not otherwise.")
i('Winged', '000300', 'C', 'Armour rune', 'Armour property', None, 'Levels 13+',
  "Winged gives a fly Speed of 25 feet, or his land Speed if slower, for five minutes once an hour. Fly becomes a studious spell at 13 and gives a better fly Speed, so the rune is only worth it if Cyrus wants to keep that slot for something else.")

# Spellhearts
i('Vigilant Eye', '120002', 'B', 'Spellheart', 'Spellheart', (9, 'Situational'), 'Levels 9+',
  "On armour, Vigilant Eye stops Cyrus being off-guard to hidden or undetected creatures of level 9 or lower. On a weapon, it lowers the flat check against concealed targets to DC 4 and against hidden or undetected targets to DC 10, which protects Spellstrikes against blur, darkness and invisibility. The armour effect applies up to a fixed level, so it loses value as enemies rise above that level, and the weapon effect, in place of the Doorknob, is the better use against an invisible or blinking enemy.")
i('Devilwing Badge', '300101', 'B', 'Spellheart', 'Spellheart', (3, 'Option'), 'Levels 3–9',
  "Devilwing Badge casts Divine Lance, an attack-roll cantrip, so a Spellstrike through it uses Aspera's attack roll, and afterwards Aspera deals an extra 1d4 spirit damage until the end of Cyrus's next turn. Spirit damage hurts almost everything with a spirit, so it is a good alternative to Flaming Star and Jolt Coil, especially against undead and fiends. Clay Sphere is still the better choice at low level, because it changes Aspera's damage type and enlarges its damage die.")
i('Rime Crystal', '300101', 'B', 'Spellheart', 'Spellheart', (3, 'Option'), 'Levels 3–9',
  "Rime Crystal casts Frostbite, and afterwards Aspera deals an extra 1d4 cold damage until the end of Cyrus's next turn. A cantrip cast from a spellheart can use his own spell DC when it is higher than the item's, so Frostbite stays effective as he gains levels. It is a Fortitude save spell, which complements his attack-roll cantrips, but Clay Sphere is still the better choice at low level, because it changes Aspera's damage type and enlarges its damage die.")

# Worn items
i('Thunderblast Slippers', '200330', 'B', 'Worn item', 'Invested', (9, 'Option'), 'Levels 9–13',
  "Thunderblast Slippers give a +2 item bonus to Acrobatics, and once a day Cyrus can Stride up to 60 feet for two actions without triggering reactions, with a small area of damage where he stops if he moved at least 30 feet. That is a reliable way to reach an enemy behind the front line, or to get out when he is surrounded, in the day's most important fight. He has no other footwear until Propulsive Boots at 13, so the slippers are useful in the meantime.")
i('Cloak of Illusions', '010311', 'B', 'Worn item', 'Invested', (7, 'Option'), 'Levels 7–10',
  "Cloak of Illusions casts Invisibility on Cyrus once a day for two actions, gives a +1 item bonus to Stealth, and grants Figment as a cantrip. Before Dimensional Disappearance at 10, a daily Invisibility lets him approach unseen, and his first Strike from invisibility is against an off-guard target, which brings Laughing Shadow's extra damage. After 10 it is useful mainly for scouting.")
i('Sash of Prowess', '200102', 'B', 'Worn item', 'Invested', (10, 'Option'), 'Levels 10+',
  "Sash of Prowess gives a +2 item bonus to Athletics and Acrobatics, and once a day turns a successful Athletics or Acrobatics check into a critical success. Like the armbands, its Athletics bonus doesn't add to Trips with Aspera, which already use the weapon's potency bonus, and the daily critical success adds only 1d6 damage to a Trip. It matters more for Tumble Through, Escape or climbing. The manoeuvres in which a critical success changes the result most, Disarm and Grapple, need a free hand, which Cyrus does not have while wielding Aspera. It does everything Armbands of Athleticism does for Cyrus and more, so it replaces them as the Athletics item at 10.")
i('Bracelet of Dashing', '000201', 'C', 'Worn item', 'Invested', None, 'Levels 3–6',
  "Bracelet of Dashing gives +1 to Acrobatics and, once a day, a +10-foot status bonus to Speed for a minute. Laughing Shadow's Speed bonus is also a status bonus, and the two don't add together, so in Arcane Cascade the bracelet only adds 5 feet.")
i('Eye of Fortune', '110001', 'C', 'Worn item', 'Invested', (13, 'Situational'), 'Levels 13+',
  "Eye of Fortune lets Cyrus roll the flat check against a concealed or hidden creature twice and keep the better result, without spending an action. It protects his Spellstrikes against blur and invisibility, but Cat's Eye Elixir and the Vigilant Eye cover the same problem without an investment slot.")
i('Bracers of Missile Deflection', '030000', 'C', 'Worn item', 'Invested', None, 'Levels 3–6',
  "Once a day these bracers give +2 AC against a ranged weapon attack that has already hit, which can turn it into a miss. It is a cheap early defence, but it uses Cyrus's reaction, which he keeps for Reactive Strike from 6, and it works only against ranged weapons.")
i('Charm of Resistance', '040000', 'C', 'Worn item', 'Invested', (6, 'Situational'), 'Levels 6+',
  "Charm of Resistance gives resistance 5 to one energy type. It is worth investing when many enemies use one element, and the Energy-Resistant armour rune does the same without using an investment slot.")
i('Ring of Sustenance', '000003', 'C', 'Worn item', 'Invested', None, 'Levels 7+',
  "Ring of Sustenance removes the need to eat or drink and lets Cyrus rest in two hours. That is useful on long journeys and for taking more of the night watch, but it does nothing in a fight.")
i('Bands of Force', '000000', 'D', 'Worn item', 'Invested', None, 'Levels 8+',
  "Bands of Force give an item bonus to AC as if they were armour, so they don't add anything for a character wearing Lattice Armor or Scale Mail.")
i('Shadow Signet', '200100', 'C', 'Worn item', 'Invested', None, 'Levels 10+',
  "Shadow Signet lets a spell attack roll target Fortitude or Reflex DC instead of AC. It applies only to spells Cyrus casts without a Strike. A Spellstrike uses Aspera's Strike, which still targets AC, so the signet helps only on the occasional turn when he casts Disintegrate or another attack spell from range.")
i('Avalanche Boots', '300002', 'C', 'Worn item', 'Invested', (17, 'Option'), 'Levels 17+',
  "Avalanche Boots are a Strength apex item with a +3 item bonus to Athletics and a stronger Shove. They give the same Strength and Athletics as Bracers of Strength, but they take the footwear slot, which means giving up Propulsive Boots or greater Boots of Bounding, so the bracers are the better Strength apex.")
i("Titan's Grasp", '300002', 'C', 'Worn item', 'Invested', None, 'Levels 18+',
  "Titan's Grasp is a Strength apex item with a +3 item bonus to Athletics and a strong once-a-day clap. The clap needs both hands free, and the gloves replace Healer's Gloves, so Bracers of Strength are the better Strength apex for Cyrus.")
i('Sandals of the Stag', '300202', 'C', 'Worn item', 'Invested', None, 'Levels 18+',
  "Sandals of the Stag are a Strength apex item that also give a +5-foot item bonus to Speed. That Speed bonus doesn't add to the bonus from boots or the Shawl of Seasons, and they take the footwear slot, so they only make sense if Cyrus has no other footwear he wants.")

# ───────── Additional consumables (survey of the rules data) ─────────
# Healing and defence
c('Mortalis Coin', '050000', 'A', 'Healing and defence', "Mortalis Coin is an armour talisman that triggers when Cyrus drops to 0 Hit Points: a critical hit that would leave him dying 2 leaves him dying 1 instead, and for 10 minutes he dies at dying 5 rather than 4. It costs no action and needs no hands, and it is the cheapest insurance against the one hit that kills a front-liner outright. Keep one on the armour whenever the attachment slot isn't needed for something else.")
c('Guardian Rose', '050000', 'B', 'Healing and defence', "Guardian Rose triggers when Cyrus would drop to 0 Hit Points: he stays up and heals 2d8+5, at the cost of being enfeebled 1 until the end of his next turn. It keeps him acting rather than dying, but the healing is fixed, so it is strongest at low levels and falls behind the Mortalis Coin later. It is an armour talisman.")
c('Fade Band', '240000', 'B', 'Healing and defence', "Fade Band is an armour talisman that casts Invisibility on Cyrus as a reaction when an attack misses him. Attacks against him then need a flat check, and his next Strike is made while he is hidden, so the target is off-guard for Laughing Shadow. It uses his reaction, which Reactive Strike also wants, and the invisibility ends when he attacks.")
c('Elysian Dew', '030000', 'B', 'Healing and defence', "Elysian Dew gives Cyrus a 10-foot aura for a minute in which he and allies gain 5 temporary Hit Points each turn and a +1 item bonus to saves. Fighting at the centre of the party's front line, he usually has allies within 10 feet, so one action buys protection for several people. It is a potion, so it fits in a Potion Patch.")
c('Invisibility Potion', '200203', 'B', 'Healing and defence', "Invisibility Potion casts Invisibility on Cyrus for one action. Drunk before a fight, it lets him approach unseen, and his first Strike is against an off-guard target for Laughing Shadow; outside combat it is a scouting tool. After Dimensional Disappearance at 10 he gets invisibility without it.")
c('Oak Potion', '030000', 'C', 'Healing and defence', "Oak Potion gives Oaken Resilience for 10 minutes: resistance to bludgeoning and piercing, but weakness to fire. It suits a fight against soldiers or beasts without fire, drunk before the fight.")
c('Bottled Omen', '030000', 'C', 'Healing and defence', "Bottled Omen lets Cyrus roll one saving throw twice within a minute of drinking it. The short window means it has to be drunk at the start of a fight against a known caster, and it is used up on the first save, which may not be the dangerous one.")
c('Panacea', '030003', 'B', 'Healing and defence', "Panacea tries to counteract every curse and disease on the drinker, along with blindness and deafness from spells. It is the answer to a curse that the party's spells can't remove, so one belongs in the party's supplies from the teens.")
c('Elixir of Life', '040000', 'C', 'Healing and defence', "Elixir of Life heals about as much as a healing potion of its level and adds a bonus against poisons and diseases. It is an elixir rather than a potion, so it can't go in a Potion Patch, which makes the healing potion the better choice for Cyrus.")
c('Warding Element Draught', '030000', 'C', 'Healing and defence', "Warding Element Draught gives a +1 item bonus to AC and saves against effects of one element for its duration. It is worth drinking before a fight against a known elemental enemy, and not otherwise.")
c('Salve of Mental Pattern', '030000', 'B', 'Healing and defence', "Salve of Mental Pattern gives resistance 10 to mental damage for 10 minutes. Applied before a fight against a psychic, an aberration or a mind-blasting caster, it removes a large part of their damage; it needs hands to apply, so it is a pre-fight item.")
c('Time Shield Potion', '030000', 'C', 'Healing and defence', "Time Shield Potion removes Cyrus from the fight for 2d4 rounds, immune to everything. It can save his life against a lethal ongoing effect, but it also takes him out of the fight for an unpredictable time.")
# Weapon treatments
c('Reactive Flash', '300001', 'B', 'Weapon treatments', "Reactive Flash is a whetstone applied to Aspera. While it lasts, the target of a Strike Cyrus makes as a reaction, such as Reactive Strike, must succeed at a Reflex save or be off-guard against it. That adds Laughing Shadow's off-guard damage to his Reactive Strikes, which suits a reach fighter who controls a lot of space.")
c('Oil of Swiftness', '300300', 'B', 'Weapon treatments', "Oil of Swiftness gives Aspera the Quickstrike rune for a minute, so Cyrus is quickened with an extra action that can only be a Strike. Before Hasted Assault at 14 that is a free extra Strike every round of a long fight, best made before the Spellstrike when the multiple attack penalty is lowest. Applying it takes a hand and an action, so it goes on just before contact.")
c('Oil of Keen Edges', '300000', 'C', 'Weapon treatments', "Oil of Keen Edges gives Aspera the Keen rune for a minute. It is worth it before a boss fight if Keen isn't one of Aspera's runes, especially with Fearsome and the Doorknob adding effects to every critical hit.")
c('Oil of Revelation', '100003', 'B', 'Weapon treatments', "Oil of Revelation makes the first creature Aspera damages glow for a minute, so an invisible enemy becomes merely hidden to the party. Against invisible stalkers it turns a fight the party can't target into one it can, after a single hit.")
c('Limning Gem', '100002', 'C', 'Weapon treatments', "Limning Gem outlines anything Aspera hits, so an invisible target becomes concealed until the end of Cyrus's next turn. It does the same job as Oil of Revelation for less time.")
c("Slayer's Stone", '300000', 'C', 'Weapon treatments', "Slayer's Stone adds 1d6 precision damage against one creature type for a minute. It is a cheap boost for a known enemy type, but precision damage is ignored by some of the creatures it targets, such as many constructs and oozes.")
c('Bane Oil', '300000', 'C', 'Weapon treatments', "Bane Oil gives Aspera a Bane rune against one creature type for a minute. It does the same job as Slayer's Stone and is a pre-fight option against a known enemy type.")
c('Valorous Coin', '310000', 'C', 'Weapon treatments', "Valorous Coin gives temporary Hit Points and a +1 bonus to attacks and damage when Cyrus falls below a quarter of his Hit Points, followed by fatigue. It helps him finish a fight while badly hurt, but the fatigue lasts until he is fully healed.")
# Offense
c('Dazing Coil', '420000', 'B', 'Offense', "Dazing Coil is a weapon talisman: when Aspera damages an off-guard creature, the target must succeed at a Will save or be stunned 1, or stunned 2 on a critical failure. Stunning a boss for an action is very strong, and Cyrus's turns are built around off-guard targets. Aspera can hold only one talisman or spellheart, so using it means swapping the Doorknob off for a 10-minute Affix, which is worth doing before a planned boss fight.")
c('Grinning Pugwampi', '410000', 'B', 'Offense', "Grinning Pugwampi is a weapon talisman that triggers when Aspera damages an off-guard creature: on a failed Will save the target rolls twice and takes the worse result on its checks for a time, and even a success affects its next check. Like the Dazing Coil, it needs the spellheart swapped off Aspera, so it is a planned-fight item for a boss.")
c("Gorum's Tear", '300000', 'C', 'Offense', "Gorum's Tear lets Cyrus roll one attack twice and keep the better result, then leaves him off-guard to that target until his next turn. It works like a free Sure Strike, but it needs Aspera's spellheart swapped off, and Sure Strike from a rank-1 slot does the same thing without that cost.")
c("Murderer's Knot", '310000', 'C', 'Offense', "Murderer's Knot makes an off-guard target Cyrus damages bleed, and keeps it off-guard until the bleed ends, which can extend Laughing Shadow's bonus for several rounds. It needs Aspera's spellheart swapped off, and creatures immune to bleed ignore it.")
c('Dispelling Sliver', '310003', 'B', 'Offense', "Dispelling Sliver tries to counteract one spell on a creature Aspera damages, as a rank-8 Dispel Magic. Against an enemy caster protected by its own buffs it can strip the most important one with no action. It needs Aspera's spellheart swapped off, so it is for a planned fight against a known caster.")
c('Wolf Fang', '200000', 'C', 'Offense', "Wolf Fang deals damage equal to Cyrus's Strength modifier when he successfully Trips. It is a cheap early bonus, but it takes the armour's attachment slot from more important talismans.")
c('Phoenix Flask', '200400', 'B', 'Movement', "Phoenix Flask gives a 40-foot fly Speed for a minute, and the first time each round Cyrus flies he deals fire damage to creatures around him. It is the Potion of Flying with damage attached, and it fits in a moderate Potion Patch.")
# Movement
c('Potion of Flying (Standard)', '000400', 'B', 'Movement', "Potion of Flying gives a 40-foot fly Speed for a minute for one action. Against flying enemies or on a vertical battlefield it is the difference between reaching the fight and not, and it fits in a Potion Patch.")
c('Feather Step Stone', '000300', 'C', 'Movement', "Feather Step Stone lets Cyrus ignore difficult terrain for one turn as a free action when he Strides or Steps. It is useful against terrain-control spells, but it takes the armour's attachment slot.")
c('Potion of Emergency Escape', '000300', 'C', 'Movement', "Potion of Emergency Escape makes Cyrus flee from every enemy with a large Speed bonus. It gets him out of a lost fight, but the fleeing condition stops him helping the party for the minute it lasts.")
# Mission supplies
c('Runestone', '000003', 'B', 'Mission supplies', "A runestone holds one rune that isn't etched into an item. Cyrus needs one at 8, when Astral takes Aspera's only property slot: Fearsome moves to a runestone and returns to Aspera at 10, rather than being lost or bought again.")
c('Glimmering Missive', '100002', 'C', 'Mission supplies', "Glimmering Missive covers creatures in a burst with glowing dust for an hour, so they can't be concealed and invisible ones become easier to target. It takes two actions and hands, so it is for an ambush the party expects.")

# ───────── Precious material armour ─────────
i('Orichalcum Armor', '030002', 'A', 'Armour material', 'Armour material', (20, 'Option'), 'Level 20',
  "Orichalcum armour holds four property runes instead of three, so at 20 Cyrus can keep Sunweave, greater Fortification and Antimagic and add a fourth, such as Spellwatch or greater Dread. Its +1 circumstance bonus to initiative doesn't stack with the +2 circumstance bonus from Incredible Initiative, so the extra rune is the whole benefit. A suit of Lattice Armor costs 66,000 gp, and the runes move across at the usual 10% of their price. It is the best armour material at 20, although high-grade djezet gives the same fourth rune a level earlier for less.")
i('Djezet Armor', '030002', 'B', 'Armour material', 'Armour material', (19, 'Option'), 'Levels 12+, high grade from 19',
  "High-grade djezet armour holds a fourth property rune, the same benefit as orichalcum, at level 19 and for 42,000 gp in Lattice Armor against orichalcum's 66,000 gp at 20. Moving runes onto djezet armour also costs nothing beyond the runes themselves, though moving them off it again costs the usual 10%. Standard grade at 12 has only the free transfer, which saves a few hundred gold, so djezet is worth buying at high grade or not at all.")
i('Keep Stone Armor', '040000', 'B', 'Armour material', 'Armour material', None, 'Level 20',
  "Keep stone armour raises its item bonus to AC and saving throws by 1 against spells, and divination spells that target Cyrus need a DC 5 flat check to work. At 20 that is +1 AC against spell attacks and +1 to every save against a spell, a large defensive gain, but it costs about 67,000 gp in Lattice Armor and holds only three property runes, so choosing it means giving up the fourth rune that orichalcum allows. It is the better choice if enemy spellcasters are the main threat at high levels.")
i('Dragonhide Armor', '020000', 'C', 'Armour material', 'Armour material', None, 'Levels 12+, high grade from 19',
  "Dragonhide armour is immune to one damage type and gives a +1 circumstance bonus to AC and saves against attacks and spells that deal it: force for an arcane dragon, spirit for a divine one, mental for an occult one and poison for a primal one. Force and spirit damage are both common from enemy casters. Dragonhide can only replace leather, hide or metal plates, so it can't make Lattice Armor, but a Breastplate has exactly the same numbers (+4 AC, Dexterity cap +1, Strength +3, Bulk 2), so a dragonhide breastplate is a real option at 12 for 1,920 gp. It needs the hide of the right kind of dragon, which is more likely to come from play than from a shop.")
i('Dawnsilver Armor', '001001', 'C', 'Armour material', 'Armour material', None, 'Levels 12+, high grade from 19',
  "Dawnsilver makes Lattice Armor 1 Bulk instead of 2, lowers its Strength threshold by 1 and reduces its Speed penalty by 5 feet. Cyrus already meets the threshold, which removes the check penalty and the Speed penalty, and still meets it after Fortification raises it by 1, so the only lasting gain is 1 Bulk. At 1,920 gp at 12 it is a convenience and not a priority.")
i('Sisterstone Armor', '110000', 'D', 'Armour material', 'Armour material', None, 'Levels 5+, standard grade from 10, high grade from 18',
  "Sisterstone works in pairs: while Cyrus's armour is within 15 feet of an item made of the other colour of sisterstone, undead adjacent to either item must succeed at a Fortitude save or be enfeebled 1 while they stay adjacent. Cyrus can also use a reaction to give the ally carrying the other item resistance to damage from undead for a round. It needs an ally who carries a matching weapon or armour and stays within 15 feet. The save DCs are fixed at 15, 22 and 33 by grade, which a typical undead of the item's level passes about nine times in ten, low grade can only hold runes up to level 8, and the reaction is one he would otherwise keep for Reactive Strike, so it would be chosen for its theme and not for its effect.")
i('Cold Iron Armor', '110000', 'D', 'Armour material', 'Armour material', None, 'Levels 5+, standard grade from 11, high grade from 18',
  "Cold iron armour only affects creatures with a weakness to cold iron, and one of those that critically fails an unarmed attack against Cyrus becomes sickened 1. Critical failures on attacks are rare and Cyrus fights at reach, so this seldom happens. Low grade costs 168 gp in Lattice Armor at 5 but can only hold runes up to level 8, so it would need upgrading to standard grade (1,440 gp) by 11 for the +2 armour potency rune. A spare weapon of cold iron or the Transmuting Ingot does far more against the same enemies.")
i('Silver Armor', '110000', 'D', 'Armour material', 'Armour material', None, 'Levels 5+, standard grade from 11, high grade from 18',
  "Silver armour works like cold iron armour against creatures with a weakness to silver, and one of those that critically fails an unarmed attack against Cyrus becomes sickened 1. That seldom happens, the costs and the rune limits by grade are the same, and a silver weapon or the Transmuting Ingot is the better answer to those enemies.")
i('Adamantine Armor', '010000', 'D', 'Armour material', 'Armour material', None, 'Levels 12+, high grade from 19',
  "Adamantine armour has far more Hardness and Hit Points than ordinary armour (Hardness 14 at standard grade), which matters only when something damages the armour itself, such as an effect that corrodes worn items. It adds nothing to AC or saves.")
i('Siccatite Armor', '010001', 'D', 'Armour material', 'Armour material', None, 'Levels 12+, high grade from 19',
  "Siccatite armour protects against severe and extreme heat or cold, depending on which form of the metal it is, and deals 4 fire or cold damage to a creature that has Cyrus grabbed or restrained with its body. It adds 1 Bulk. It is worth having only for a long expedition into extreme heat or cold, and an item or spell for environmental protection does that without replacing the armour.")
i('Grisantian Pelt Armor', '010000', 'D', 'Armour material', 'Armour material', None, 'Levels 12+, high grade from 19',
  "Grisantian pelt armour is immune to fire and gives a +1 circumstance bonus to AC and saves against fire. It can only be made from armour of cloth, leather or hide, so it can't make Lattice Armor or a Breastplate, and Cyrus would lose AC by changing to hide armour.")
i('Duskwood Armor', '001000', 'D', 'Armour material', 'Armour material', None, 'Levels 12+, high grade from 19',
  "Duskwood is the wooden counterpart of dawnsilver: 1 Bulk lighter, a lower Strength threshold and a smaller Speed penalty. It applies only to armour made of wood, and Lattice Armor is metal.")
i('Dreamweb', '010000', 'D', 'Armour material', 'Armour material', None, 'Levels 5+, high grade from 14',
  "Light armour made from dreamweb is 1 Bulk lighter and gives poison resistance equal to 3 plus its armour potency. It applies only to light cloth or leather armour, so it doesn't fit Lattice Armor.")
i('Elven Chain', '000000', 'D', 'Armour material', 'Armour material', None, 'Levels 13+, high grade from 20',
  "Elven Chain is a dawnsilver chain shirt with no check penalty and without the noisy trait. A chain shirt is light armour with +2 AC and a Dexterity cap of +3, so with Dexterity +1 Cyrus would lose 2 AC compared with Lattice Armor.")
i('Inubrix Armor', '000000', 'D', 'Armour material', 'Armour material', None, 'Levels 11+, high grade from 18',
  "Inubrix gives metal armour the flexible trait, lowers its item bonus to AC by 1 and raises its Dexterity cap by 1. Lattice Armor would go from +4 with a cap of +1 to +3 with a cap of +2, a net loss of 1 AC with Dexterity +1. The flexible trait removes the check penalty from Acrobatics and Athletics, which Cyrus already avoids by meeting the Strength threshold.")
i('Noqual Armor', '010000', 'D', 'Armour material', 'Armour material', None, 'Levels 12+, high grade from 19',
  "Noqual armour gives a +1 circumstance bonus to AC against spell attack rolls, but every spell Cyrus casts while wearing it needs a DC 5 flat check or fails. That is one spell in five lost, Spellstrikes included, so it is unusable for a magus.")
i('Sovereign Steel Armor', '110000', 'D', 'Armour material', 'Armour material', None, 'Levels 13+, high grade from 20',
  "Sovereign steel armour combines cold iron's effect on creatures with a weakness to cold iron with noqual's +1 circumstance bonus to AC against spell attacks, and carries noqual's DC 5 flat check on every spell Cyrus casts. The flat check rules it out for a magus.")
i('Abysium Armor', '000000', 'D', 'Armour material', 'Armour material', None, 'Levels 12+, high grade from 19',
  "Abysium armour leaves the wearer sickened 2 at standard grade, or 3 at high grade, with no way to reduce it while it is worn and for an hour afterwards, and it can sicken every creature within 10 feet, allies included. It is meant for creatures immune to its effects.")


# ───────── Items added on 28 November 2026 (three sweeps of the rules data, and ThrabenU's recommended items) ─────────
i('Energy Vulnerability', '300002', 'B', 'Weapon rune', 'Weapon property', (4, 'Option'), 'Levels 4+, greater from 16',
  "Energy Vulnerability makes a critical hit give the target weakness 5 to one energy type, chosen when the rune is made, until the end of Cyrus's next turn. By itself that helps only when his next spell or an ally's attack deals that type. Once Aspera also carries a rune of the same type, such as Flaming, every Strike made while the weakness lasts benefits from it. It does nothing against a target that resists or is immune to that type, or that already has a larger weakness to it. Fearsome does more for all his allies on the same critical hit, so Energy Vulnerability is a rune for later levels, and it is at its best as the greater version beside an energy rune of the same type.")
i('Vitalizing', '300000', 'B', 'Weapon rune', 'Weapon property', (5, 'Situational'), 'Levels 5+, greater from 14',
  "Vitalizing adds 1d6 persistent vitality damage against undead on every hit, and a critical hit also leaves the undead enfeebled 1 until the end of Cyrus's next turn. Against undead it deals more damage than the other runes of its level, because persistent damage continues between his turns. Against everything else it does nothing, so it belongs on Aspera only while undead are the main enemy and is kept on a runestone when they are not.")
i('Holy', '300000', 'B', 'Weapon rune', 'Weapon property', (11, 'Option'), 'Levels 11+',
  "Holy adds 1d4 spirit damage to every hit and 2d4 against unholy targets, and gives Aspera's Strikes the holy trait, which sets off any weakness to holy. Once a day a critical hit on an unholy creature heals Cyrus for twice its level. Anyone who is not unholy can use it. Against unholy enemies it is the strongest rune at its level, while against others its 1d4 is less than Frost or Flaming adds. Both it and Astral deal spirit damage, so carrying the two leaves Aspera with little against creatures that have no spirit, such as constructs.")
i('Hopeful', '300000', 'B', 'Weapon rune', 'Weapon property', (11, 'Option'), 'Levels 11+',
  "Hopeful gives allies within 30 feet a +1 status bonus to attack rolls until the end of Cyrus's next turn whenever he critically hits. With several allies attacking, that is worth more damage than any die a rune adds to his own Strike, and unlike Fearsome it helps against every enemy, including those immune to fear. It is a status bonus, so it adds nothing for allies who already have one. The rune limits the bonus to allies who share an alignment component with him, so it may not reach every ally. Greater Fearsome is stronger against a single enemy that can be frightened, and Hopeful is the better rune when enemies are numerous or immune to fear.")
i('Extending', '100100', 'C', 'Weapon rune', 'Weapon property', None, 'Levels 9+, greater from 13',
  "Extending spends two actions to make one Strike at a reach of 60 feet. The activation is its own activity, so it cannot be the Strike inside a Spellstrike, and two actions for a single Strike with no spell in it is a poor turn for a magus. Its one use is against an enemy he cannot reach when no spell fits, which Fly and his ranged spells cover better.")

i('Deathbane Crescent', '310000', 'B', 'Spellheart', 'Attachment', (3, 'Situational'), 'Levels 3+, greater from 8, major from 12',
  "Deathbane Crescent casts Vitality Lash from the item, a cantrip that only harms undead, and Cyrus can deliver it through Spellstrike against a basic Fortitude save. After that cast, Aspera's Strikes deal an extra 1d4 vitality damage until the end of his next turn. On the armour instead he gains resistance 2 to attacks and effects from undead for the same time, rising to 5 and 10 in the greater and major versions. Against undead it is the strongest spellheart at its price, on either item. Against anything else Vitality Lash has no target, so neither benefit can be obtained, and Clay Sphere is the better attachment.")
i('Cerebral Barbell', '300100', 'B', 'Spellheart', 'Attachment', (3, 'Option'), 'Levels 3+, greater from 8, major from 12',
  "Cerebral Barbell casts Telekinetic Projectile from the item, an attack cantrip that works through Spellstrike or at 30 feet when he cannot reach. After any spell cast through it, Aspera's Strikes deal 2 extra force damage until the end of his next turn, rising to 3 and 4. That is close to what Clay Sphere's larger die adds, in a type almost nothing resists. Clay Sphere still offers more, namely all three physical damage types and a daily Enlarge, so the barbell is the alternative when a ranged cantrip matters more than those.")
i('Lightweave Scarf', '400100', 'B', 'Spellheart', 'Attachment', (8, 'Option'), 'Levels 8+',
  "On Aspera, Lightweave Scarf adds an effect to its daily Hypnotize: after that casting, his next Strike that hits leaves the target confused for a round, with no saving throw. A confused enemy is off-guard, cannot use reactions and attacks targets at random, so a single strong enemy may spend its turn on its own allies. If the Strike inside a Spellstrike of Hypnotize does not count as that next Strike, the effect takes a casting on one turn and a Strike by the end of the next. Its cantrip, Light, is not an illusion and does not set the effect off, and the effect is visual. It works once a day, so the greater Phantasmal Doorknob gives more over a whole day and the scarf gives more in the day's most important fight.")
i('Energizing Vial', '202200', 'B', 'Spellheart', 'Attachment', (7, 'Option'), 'Levels 7+, greater from 13',
  "Energizing Vial casts Live Wire from the item, an attack cantrip that still deals electricity damage on a miss, so it is a sound spell for a Spellstrike on a turn when he is not spending a slot. On the armour, casting it lets him Step as a free action once a round until the end of his next turn, so he can strike and step back out of an enemy's reach, or move to a flank, without spending an action. On Aspera it adds 1d4 persistent electricity damage to Strikes for the same time. The armour version is the better use, and it is the strongest candidate for the armour's attachment at the levels where he often casts cantrips.")
i('Trinity Geode', '030000', 'B', 'Spellheart', 'Attachment', (3, 'Option'), 'Levels 3+, greater from 8, major from 12',
  "On the armour, Trinity Geode gives resistance to physical damage until the end of Cyrus's next turn after he casts Scatter Scree through it: 1 at first, 3 in the greater version and 5 in the major. Because it lasts through his next turn, casting the cantrip on one turn in two maintains it for a whole fight, and resistance to every physical hit is the protection someone fighting at the front uses most. The cost lies in the spell itself, because Scatter Scree is a weak Reflex cantrip that affects only the target in a Spellstrike, and each turn spent on it is a turn without a stronger spell. It suits the levels at which he often casts cantrips and loses its value once he has a slot to spend in every round. On Aspera it adds only 1d4 bludgeoning damage.")
i('Judgement Thurible', '130000', 'B', 'Spellheart', 'Attachment', (10, 'Option'), 'Levels 10+',
  "Judgement Thurible works only for a character who worships a deity. On the armour, each cast of Divine Lance through it puts a rank-3 Protection on Cyrus for a round: a +1 status bonus to AC and saves for him and, at that rank, for allies within 10 feet. Divine Lance is an attack cantrip, so the cast can be a Spellstrike. On Aspera the cast instead gives the weapon the holy rune until the end of his next turn, if his deity allows it. The armour effect lasts one round, so it needs the cantrip every turn, and at reach his allies are often more than 10 feet away.")
i("Ghostcaller's Planchette", '040000', 'B', 'Spellheart', 'Attachment', (12, 'Option'), 'Levels 12+',
  "On the armour, Ghostcaller's Planchette gives resistance 5 to all physical damage until the start of Cyrus's next turn after he casts Void Warp through it, and 10 in the greater version. That is substantial protection for a round, but it needs the cantrip every turn, and Void Warp targets only living creatures, so against anything else the spell cannot be cast to obtain it. The major Trinity Geode gives the same resistance for two turns per cast and works against any target. On Aspera the cast grants Ghost Touch, which Astral already includes.")
i('Desolation Locket', '020110', 'B', 'Spellheart', 'Attachment', (8, 'Option'), 'Levels 8+, greater from 13',
  "On the armour, Desolation Locket gives a +2 item bonus to saves against emotion effects, one more than a resilient rune of the same level, which covers fear, despair and most charms. It also casts Haunting Hymn as a cantrip and Fear once a day. On Aspera, a non-cantrip cast through it surrounds him with a 5-foot aura that can slow creatures that end their turn there, which his enemies rarely do when he fights at reach. As an armour attachment it works without any action from him, and its limit is the modest size of the bonus.")
i("Jyoti's Feather", '210010', 'B', 'Spellheart', 'Attachment', (10, 'Situational'), 'Levels 10+',
  "On Aspera, Jyoti's Feather gives the weapon the Vitalizing rune for as long as it is affixed, without using a property slot: 1d6 persistent vitality damage to undead on every hit. On the armour it gives a +2 item bonus to saves against death and void effects. Either way it casts Stabilize at will and Vital Beacon once a day, which places a store of healing before a fight that he and his allies can draw on by touch. Against undead the weapon version amounts to an extra rune at no cost in slots. Against other enemies it gives up the Phantasmal Doorknob's blindness and gains nothing, so it goes on Aspera only when undead are expected.")
i('Enigma Mirror', '020120', 'B', 'Spellheart', 'Attachment', (7, 'Option'), 'Levels 7+, greater from 10, major from 13',
  "Enigma Mirror is worth its place for its daily spells, which need no slot: Blur at 7, Mirror's Misfortune in the greater version, and Mirror Malefactors as well in the major version, cast at the item's DC. Blur is one of his studious spells, so the base version saves a rank-2 slot once a day. The effects that follow an illusion cast through it, concealment for an ally on the armour or Thicket of Knives on Aspera, come only from those daily spells, because its cantrip, Forbidding Ward, is not an illusion. As an armour attachment it asks nothing of his turns and adds one good spell a day.")
i('Saurian Spike', '100003', 'B', 'Spellheart', 'Attachment', (9, 'Option'), 'Levels 9+, greater from 11',
  "On the armour, Saurian Spike gives imprecise scent out to 30 feet, 60 in the greater version, so an invisible or hidden creature within that range can be placed in its square without an action, and it casts Gouging Claw from the item. That makes it a natural armour attachment once the greater Phantasmal Doorknob takes Aspera's slot at 10, since he keeps Gouging Claw without a cantrip slot and gains a permanent means of locating invisible creatures. Clay Sphere on the armour offers a daily Enlarge instead. The weapon effect and the daily Dinosaur Form are meant for a character who fights in a battle form and do nothing for him.")

i('Blazing Banner', '300000', 'B', 'Banner', 'Affixed to Aspera', (4, 'Option'), 'Levels 4+, greater from 12',
  "Blazing Banner adds 1d4 persistent fire damage to every critical hit that Cyrus or an ally within 30 feet makes with a Strike. Affixed to Aspera it takes no hand, no investment and no rune slot, so its only cost is its price. Its value grows with the number of allies who Strike and falls against enemies that resist fire. It is the inexpensive banner to start with.")
i("Knave's Standard", '200000', 'C', 'Banner', 'Affixed to Aspera', None, 'Levels 4+, greater from 12',
  "Knave's Standard adds 1d4 precision damage to critical hits against off-guard targets for everyone within 30 feet. Most critical hits are scored against off-guard targets, so it applies nearly as often as Blazing Banner, but one extra die is worth less than persistent fire that keeps burning. It is the choice only against enemies that resist fire, and it does nothing to creatures immune to precision damage.")
i("Stalwart's Banner", '030000', 'B', 'Banner', 'Affixed to Aspera', (7, 'Option'), 'Levels 7+, greater from 12',
  "Stalwart's Banner spends one action, once a minute, to give Cyrus and every ally within 30 feet 5 temporary Hit Points for a round, 10 and 15 in the later versions, with a bonus against being moved or knocked prone. With many allies in range, one action provides more Hit Points than any healing of its level, provided an area attack or several enemy turns follow in that round. The cost is the action, which a magus can rarely spare. The activation also requires the banner to be held, and it is not certain that wielding the weapon it is affixed to satisfies that.")
i('Arcane Standard', '300000', 'B', 'Banner', 'Affixed to Aspera', (10, 'Option'), 'Levels 10+',
  "Arcane Standard spends one action, once a turn, to give a creature within 30 feet weakness 5 to an energy type it has taken damage from that turn, for a round. After a Spellstrike with an energy spell, every further hit of that type from him or an ally in that round does 5 more, and an energy rune on Aspera makes each of his own Strikes count. The action is the one he would spend recharging Spellstrike, so it suits the turns when several allies can attack the same target. Like Stalwart's Banner, its activation requires the banner to be held.")
i('Hexwise Banner', '040000', 'A', 'Banner', 'Affixed to Aspera', (10, 'Option'), 'Levels 10+',
  "Hexwise Banner gives Cyrus and every ally within 30 feet resistance 5 to damage from spells, applied once to a spell that deals damage several times. It needs no activation, so on Aspera it works from the first round without an action, and it protects all his allies against the area spells that hurt a group most. It is the strongest banner for general use from 10. It does nothing against attacks and abilities that are not spells, and only the major version at 20 improves it.")
i('Swift Standard', '003000', 'B', 'Banner', 'Affixed to Aspera', (12, 'Option'), 'Levels 12+, greater from 15',
  "Swift Standard gives Cyrus and allies who start their turn within 30 feet a +5-foot status bonus to land Speed, +10 and +15 in the later versions. It is a status bonus, so it adds nothing for anyone already under Tailwind. Allies without that spell gain 5 feet of Speed at no cost in actions, while Cyrus, if he uses a wand of Tailwind, gains nothing himself.")
i('Beacon of the Wilds', '004001', 'B', 'Banner', 'Affixed to Aspera', (14, 'Option'), 'Levels 14+',
  "Beacon of the Wilds lets Cyrus and his allies ignore difficult terrain within 30 feet of him. That lets his side fight inside the terrain its own spells create and removes one of the commonest ways in which an enemy slows those fighting in melee. Its worth depends on how often difficult terrain appears, including the terrain his own area spells leave behind, and where it does appear nothing else gives all his allies the same freedom.")

i('Spring Heel', '003400', 'A', 'Worn item', 'Worn, not invested', (5, 'Option'), 'Levels 5+',
  "Spring Heel spends one action, once an hour, to Stride up to twice his Speed or Leap 20 feet. In most fights that gives him a second Stride at no cost, which is the same gain as the best option of the Tactician's Helm without needing a charge, and it is not invested. The item is made as a pair of prosthetic legs, so for Cyrus it would have to take another form. In such a form it is among the best purchases at its level for a magus, who is always an action short.")
i('Aeon Stone (Preserving)', '020000', 'B', 'Worn item', 'Invested', (5, 'Option'), 'Levels 5+',
  "The preserving aeon stone gives resistance 3 to persistent damage and ends the condition at the end of any turn when the damage fails to get through. Small persistent effects, such as the 1d4 and 1d6 that runes, poisons and bleeding add, mostly end the first time they would deal damage, while larger ones are only reduced. It is invested, and Kindler Cameo already ends persistent damage once a day, so it is worth wearing only while he has investment to spare.")
i("Charlatan's Cape", '010310', 'B', 'Worn item', 'Invested', (10, 'Option'), 'Levels 10+',
  "Charlatan's Cape casts Translocate once a day for two actions and leaves smoke at both ends that conceals anyone inside until the end of his next turn. A Translocate that costs no slot saves one of rank 4, and arriving concealed makes an escape or an approach safer. It also gives +2 to Deception. It is worn as a cloak, and it becomes available at the level where the Cloak of Illusions stops being useful.")
i('Soft-Landing', '000002', 'C', 'Worn item', 'Applied to boots or a cloak', None, 'Levels 3+',
  "Soft-Landing shortens every fall by 10 feet and, once a day as a reaction, gives him Feather Fall. It is applied to boots or a cloak and is not invested, so it costs only its price. It is useful to someone who jumps and teleports around high ground, and loses its value once he can cast Fly regularly.")
i('Thrasher Tail', '110000', 'C', 'Worn item', 'Worn, not invested', (9, 'Situational'), 'Levels 9+',
  "Thrasher Tail gives a reaction when Cyrus is grabbed, which deals 8d6 slashing damage to the creature holding him against a fixed basic Reflex DC of 25 and frees him whatever the result. It resets in 10 minutes and is not invested. Dimensional Assault already takes him out of a grab, since it has neither the move nor the manipulate trait, so the tail is for fights in which he has no Focus Point or cannot see a space to teleport to. It is made as a prosthetic tail, so for Cyrus it would have to take another form.")
i('Umbral Wings', '003100', 'B', 'Worn item', 'Invested', (8, 'Option'), 'Levels 8+',
  "Umbral Wings gives a fly Speed equal to his Speed until the end of his next turn, for one action once an hour, with low-light vision and +1 to Seek. That gives him flight in most fights without a slot or two actions of casting, which is enough to reach a flying enemy or to cross a gap and land. It ends at the end of his next turn, so it does not replace Fly for a fight in the air. It is invested.")
i('Rune of Sin', '050000', 'A', 'Worn item', 'Invested', (12, 'Option'), 'Levels 12+',
  "Rune of Sin gives resistance 10 to damage from divine spells until the start of his next turn whenever Cyrus casts an arcane spell. He casts one on nearly every turn, a Spellstrike included, so in practice the resistance is always in effect. Against enemies who cast divine spells it is the largest constant protection he can buy at 12, and against everyone else it does nothing. It is invested, so whether it is worth wearing depends on how often he faces divine spellcasters.")
i('Silent Heart', '020001', 'B', 'Worn item', 'Invested', (5, 'Option'), 'Levels 5+',
  "Once an hour, Silent Heart lets Cyrus use a reaction before rolling to gain a +2 status bonus to a save against an emotion effect or one that would leave him controlled. Those are the saves that someone fighting at the front can least afford to fail, and once an hour means once in most fights. It also gives +1 to Occultism. It uses the reaction he also wants for Reactive Strike, and the bonus does not add to another status bonus to saves. It is invested and inexpensive.")
i('Staring Skull', '030000', 'B', 'Worn item', 'Invested', (8, 'Option'), 'Levels 8+',
  "Staring Skull stops Cyrus dying when his dying value would reach the point of death, holding it one short, once a day. It can also stop a death effect from a weak enough source. It works twice in total and is then spent. For someone who fights at the front it guards against a single disastrous round, and it needs no action. Its real cost is the investment it takes up.")
i('Soaring Wings', '003010', 'B', 'Worn item', 'Invested', (9, 'Option'), 'Levels 9+, greater from 14',
  "Soaring Wings gives a fly Speed equal to his land Speed for 10 minutes, once a day, for two actions, and the greater version at 14 works once an hour. It stands in for a casting of Fly, which frees a rank-4 slot each day, and lasts twice as long. From 13 Fly is one of his studious spells and the saving is smaller. It is invested.")

i('Wand of Fey Flames', '000021', 'C', 'Held item', 'Held', (7, 'Situational'), 'Levels 7+',
  "Wand of Fey Flames casts Revealing Light once a day, and creatures affected by it must succeed at a Will save or take a -2 status penalty to Will saves against his illusion and mental spells while the light lasts, and those spells also reach them at twice their range. One casting therefore makes his Will spells more likely to succeed against a whole group. It needs a hand for the wand, two actions for the casting and a turn before the spell that benefits, so it suits a planned fight begun from range and not a turn in melee.")
i('Spellstriker Staff', '200020', 'C', 'Held item', 'Fused into Aspera', None, 'Levels 7+, greater from 11, major from 16',
  "Spellstriker Staff is made for the magus. Once an hour, when a Spellstrike with a spell from a slot misses, the stored energy is released in a 5-foot emanation that deals 1d6 damage per spell rank against a basic save. Fused into Aspera it would keep that activation. With a reach weapon the target of the missed Strike is usually outside 5 feet, and allies beside him are inside it, so the protection against a miss is seldom of use. Its spell list, Sure Strike, Acid Grip, Telekinetic Maneuver and later Haste and Weapon Storm, is good but shorter than the stave planned for Aspera.")
i('Corrosive Engravings', '000020', 'C', 'Held item', 'Grimoire', None, 'Levels 5+',
  "Corrosive Engravings is a grimoire. Once a day, an acid or poison spell that deals persistent damage, such as Acid Grip or Acid Arrow, also leaves every creature that takes the persistent damage sickened 2 until that damage ends, which is a strong addition to spells he already prepares. No one can use more than one grimoire a day, so it would replace Endless Grimoire and its extra prepared spell, and its activation requires his next action to be the casting of the spell, which a Spellstrike may not satisfy. Endless Grimoire is the better book.")

i('Orichalcum Weapon', '300002', 'A', 'Weapon material', 'Weapon material', (18, 'Option'), 'Levels 18+',
  "An orichalcum weapon holds four property runes instead of three, and takes a Quickstrike rune at half price. For Aspera at 18 that is a fourth rune beside Astral, Fearsome and Ashen, such as Rooting, Flaming or Brilliant, which no other purchase can give. A weapon of 2 Bulk costs 27,000 gp, and runes move across at the usual 10% of their price. Quickstrike itself adds little for him, so the fourth slot is the whole benefit. It is the best weapon material at the level it appears.")
i('Sovereign Steel Weapon', '200000', 'C', 'Weapon material', 'Weapon material', (12, 'Situational'), 'Levels 12+, high grade at 19',
  "A sovereign steel weapon counts as cold iron and leaves a spellcaster stupefied 1 for a round on a critical hit. Standard grade at 12 holds runes up to level 15, so Aspera would need the high-grade version at 19 for its later runes. Stupefied 1 lowers a caster's spell attacks and DCs by 1 and can make a spell fail, which is useful against few enemies, and cold iron matters only against the creatures weak to it. Orichalcum's fourth rune is worth more, a level earlier and for less.")

c("Lucky Rabbit's Foot", '030000', 'B', 'Healing and defence', "Lucky Rabbit's Foot is an armour talisman: when Cyrus fails a Reflex save against a damaging effect, he rerolls it as a reaction, and if the second roll also fails he can Stride up to his Speed. Reflex is his lowest save, and the save it rescues is usually the area spell that hurts most. It shares the armour's attachment slot with the Mortalis Coin and any spellheart there, and at 175 gp each it is for fights where area damage is expected.")


# ───────── Consumable evaluations in their current wording ─────────
_CEV = {
'Healing Potion': "A healing potion heals at once, on Cyrus's own turn, without using an ally's actions, so it is worth keeping one strong enough to let him survive the next hit. Loaded in a Potion Patch it costs one action and both hands stay on Aspera. Without a patch he has to draw it, drink it and take hold of Aspera again.",
'Potion Patch': "A loaded patch lets Cyrus drink the potion inside it for one action without letting go of Aspera, which turns a healing potion or a Potion of Quickness from a three-action turn into a one-action turn. Only one patch works at a time, and its magic ends at the next daily preparations, so in practice it provides one potion a day. That is usually the healing potion, or a Potion of Quickness before a fight he has planned for. The lesser patch holds potions up to level 10, the moderate up to 15 and the greater any level.",
'Retrieval Prism': "A Retrieval Prism puts one prepared item into a free hand as a free action. It does for one item what the Retrieval Belt does, without being worn as a belt or needing investment, but it occupies the armour's attachment slot.",
"Cat's Eye Elixir": "Cat's Eye Elixir removes the flat check against concealed targets and lowers it against hidden ones within 30 feet. A Spellstrike that fails a flat check wastes the slot as well as the attack, so the elixir protects his most valuable action against fog, blur and invisibility.",
'Mistform Elixir': "Mistform Elixir makes Cyrus concealed against attacks aimed at him and does nothing against area effects. The moderate version lasts a minute, which makes it the better one to drink before a fight.",
'Numbing Tonic': "Numbing Tonic gives temporary Hit Points when it is drunk and again at the start of each of Cyrus's turns for a minute. It is an elixir, so it cannot go in a Potion Patch, and it is best drunk just before a fight against many attacks.",
'Soothing Tonic': "Soothing Tonic heals a little each round for a while, which suits recovery after a fight more than an emergency during one.",
'Potion of Quickness': "Potion of Quickness quickens Cyrus for a minute, giving him an extra Strike or Stride each turn. From a Potion Patch it costs one action, which the extra action repays on the following turn, so in a long fight it is a large gain. It is within the level limit of the lesser patch.",
'Transmuting Ingot': "A Transmuting Ingot makes Aspera count as a chosen material for a minute, which turns a known weakness to silver or cold iron into extra damage on every hit. Applying it takes an action, so it is best done before the fight or while Cyrus is out of reach.",
'Potency Crystal': "A Potency Crystal gives a weapon temporary fundamental runes for one Strike. Aspera has its own runes, so the crystal is useful only on a spare weapon.",
'Oil of Potency': "Oil of Potency gives a weapon temporary fundamental runes for a minute. It is useful only for a spare weapon whose own runes are weaker than the oil's.",
'Ghostbane Fulu': "Ghostbane Fulu is activated after a hit and lets Aspera affect that particular incorporeal creature fully. It is affixed like a talisman, and Aspera can hold only one talisman or spellheart, so using it means removing the spellheart for that fight. It is an inexpensive answer to a known incorporeal enemy before Astral is bought.",
'Escape Fulu': "Escape Fulu improves repeated Escape and Stealth checks for a minute. It is an armour talisman, so it occupies the armour's attachment slot, and it is worth affixing only when an enemy that grapples is expected.",
'Analysis Eye': "Analysis Eye reveals a weakness or resistance after a hit, which helps against several unfamiliar enemies. Magus's Analysis already provides most of that.",
'Emerald Grasshopper': "Emerald Grasshopper gives a 40-foot Leap for one action with both hands still on Aspera. It deals with gaps, ledges and rooftops that would otherwise stop a melee fighter. It is an armour talisman, so it shares the armour's single attachment slot with the Retrieval Prism, the Mortalis Coin and any spellheart on the armour.",
'Blast Boots': "Blast Boots power one large jump that has been planned for, and they still use the action of jumping. Emerald Grasshopper does the same with less preparation.",
'Gecko Pads': "Gecko Pads allow a climb that has been planned for. Gecko Grip meets the same need without requiring a free hand.",
'Oil of Skating': "Oil of Skating speeds movement on smooth or downhill ground and is of little use anywhere else.",
'Smoke Ball': "Smoke Ball creates a concealing cloud centred on Cyrus, which covers an escape. It also conceals enemies from his allies, so they need to know it is coming.",
'Oil of Mending': "Oil of Mending repairs a broken item. It is worth carrying on expeditions where a broken tool or shield would matter.",
'Energizing Tea': "Energizing Tea gives an item bonus to an Athletics or Acrobatics challenge that Cyrus knows is coming.",
'Heartening Missive (Butterfly)': "The butterfly Missive lets a recipient known to Cyrus improve one important Diplomacy or Performance check, provided it arrives in time, and that can decide a negotiation.",
'Bottled Lightning': "Bottled Lightning makes a target off-guard from range. It is better given to an ally who is ready to throw it than thrown by Cyrus, who would have to take a hand off Aspera.",
'Stumbling Fulu': "Stumbling Fulu needs access to the target's armour and has a fixed, low DC. It belongs to an infiltration more than to a fight.",
'Explosive Missive': "Explosive Missive is a burst of damage delivered by messenger and prepared in advance. Its fixed DC falls behind that of Cyrus's own spells.",
'Blight Breath': "Blight Breath gives resistance to poison while held and a short cone of damage. It is worth considering only against an enemy that relies heavily on poison.",
'Mortalis Coin': "Mortalis Coin is an armour talisman that takes effect when Cyrus drops to 0 Hit Points. A critical hit that would leave him dying 2 leaves him dying 1 instead, and for 10 minutes he dies at dying 5 instead of 4. It costs no action and needs no hands, and it is the cheapest protection against the single hit that would kill him outright. One is worth keeping on the armour whenever the attachment slot is not needed for something else.",
'Guardian Rose': "Guardian Rose takes effect when Cyrus would drop to 0 Hit Points: he stays conscious and heals 2d8+5, at the cost of being enfeebled 1 until the end of his next turn. It keeps him acting when he would otherwise be dying, but the healing is a fixed amount, so it is strongest at low levels and falls behind the Mortalis Coin later. It is an armour talisman.",
'Fade Band': "Fade Band is an armour talisman that casts Invisibility on Cyrus as a reaction when an attack misses him. Attacks against him then need a flat check, and his next Strike is made while he is hidden, so the target is off-guard and takes Laughing Shadow's extra damage. It uses the reaction he also wants for Reactive Strike, and the invisibility ends when he attacks.",
'Elysian Dew': "Elysian Dew surrounds Cyrus for a minute with a 10-foot aura in which he and his allies gain 5 temporary Hit Points each turn and a +1 item bonus to saves. He usually fights among his allies in melee, with some of them within 10 feet, so one action protects several people. It is a potion, so it fits in a Potion Patch.",
'Invisibility Potion': "Invisibility Potion casts Invisibility on Cyrus for one action. Drunk before a fight it lets him approach unseen, and his first Strike is then against an off-guard target, which brings Laughing Shadow's extra damage. Outside combat it is useful for scouting. From level 10 Dimensional Disappearance makes him invisible without it.",
'Oak Potion': "Oak Potion gives Oaken Resilience for 10 minutes, which means resistance to bludgeoning and piercing damage and a weakness to fire. It suits a fight against enemies with weapons or natural attacks and no fire, and it should be drunk before the fight begins.",
'Bottled Omen': "Bottled Omen lets Cyrus roll one saving throw twice within a minute of drinking it. Because the time is so short, it has to be drunk at the start of a fight against a known spellcaster, and it is used up on the first save, which may not be the dangerous one.",
'Panacea': "Panacea attempts to counteract every curse and disease on the drinker, along with blindness and deafness caused by spells. It is the answer to a curse that his allies' spells cannot remove, so one is worth keeping among the group's supplies from the early teens.",
'Elixir of Life': "Elixir of Life heals about as much as a healing potion of its level and adds a bonus against poisons and diseases. It is an elixir and not a potion, so it cannot go in a Potion Patch, which makes the healing potion the better choice for Cyrus.",
'Warding Element Draught': "Warding Element Draught gives a +1 item bonus to AC and saves against effects of one element for its duration. It is worth drinking before a fight against an enemy known to use that element, and not otherwise.",
'Salve of Mental Pattern': "Salve of Mental Pattern gives resistance 10 to mental damage for 10 minutes. Applied before a fight against an enemy that attacks the mind, it removes a large part of that enemy's damage. It needs free hands to apply, so it has to be used before the fight.",
'Time Shield Potion': "Time Shield Potion removes Cyrus from a fight for 2d4 rounds, during which he is immune to everything. It can save his life from a lethal continuing effect, but it also keeps him out of the fight for an unpredictable time.",
'Reactive Flash': "Reactive Flash is a whetstone applied to Aspera. While it lasts, the target of any Strike Cyrus makes as a reaction, such as a Reactive Strike, must succeed at a Reflex save or be off-guard against it. That adds Laughing Shadow's extra damage to his Reactive Strikes, which suits someone whose reach covers a large area.",
'Oil of Swiftness': "Oil of Swiftness gives Aspera the Quickstrike rune for a minute, so Cyrus is quickened with an extra action that can only be a Strike. Before Hasted Assault at 14, that is an additional Strike in every round of a long fight, and it is best made before the Spellstrike, when the multiple attack penalty is lowest. Applying the oil takes a hand and an action, so he applies it just before the two sides meet.",
'Oil of Keen Edges': "Oil of Keen Edges gives Aspera the Keen rune for a minute. It is worth using before a fight against a single powerful enemy if Keen is not one of Aspera's runes, especially when Fearsome and the Phantasmal Doorknob add effects to every critical hit.",
'Oil of Revelation': "Oil of Revelation makes the first creature Aspera damages glow for a minute, so an invisible enemy becomes merely hidden to everyone. After a single hit, a fight against an enemy that nobody could target becomes one in which everybody can.",
'Limning Gem': "Limning Gem outlines anything Aspera hits, so an invisible target becomes concealed until the end of Cyrus's next turn. It does what Oil of Revelation does, for less time.",
"Slayer's Stone": "Slayer's Stone adds 1d6 precision damage against one type of creature for a minute. It is an inexpensive addition against a known type of enemy, but some of the creatures it can be made for are immune to precision damage.",
'Bane Oil': "Bane Oil gives Aspera a Bane rune against one type of creature for a minute. It serves the same purpose as Slayer's Stone and is applied before a fight against a known type of enemy.",
'Valorous Coin': "Valorous Coin gives temporary Hit Points and a +1 bonus to attacks and damage when Cyrus falls below a quarter of his Hit Points, and leaves him fatigued afterwards. It helps him finish a fight while badly hurt, but the fatigue lasts until he is fully healed.",
'Dazing Coil': "Dazing Coil is a weapon talisman. When Aspera damages an off-guard creature, the target must succeed at a Will save or be stunned 1, or stunned 2 on a critical failure. Taking an action from a powerful enemy is very valuable, and Cyrus attacks off-guard targets as a matter of course. Aspera can hold only one talisman or spellheart, so using the coil means removing the spellheart and spending 10 minutes to affix it, which is worth doing before a fight against such an enemy that he has planned for.",
'Grinning Pugwampi': "Grinning Pugwampi is a weapon talisman that takes effect when Aspera damages an off-guard creature. On a failed Will save the target rolls twice and takes the worse result on its checks for a time, and even a success affects its next check. Like the Dazing Coil, it takes the place of Aspera's spellheart, so it is for a planned fight against a single powerful enemy.",
"Gorum's Tear": "Gorum's Tear lets Cyrus roll one attack twice and keep the better result, then leaves him off-guard to that target until his next turn. It works like a casting of Sure Strike that costs no action, but it takes the place of Aspera's spellheart, and Sure Strike from a rank-1 slot does the same without that cost.",
"Murderer's Knot": "Murderer's Knot makes an off-guard target that Cyrus damages bleed, and keeps it off-guard until the bleeding ends, which can prolong Laughing Shadow's extra damage for several rounds. It takes the place of Aspera's spellheart, and creatures immune to bleed ignore it.",
'Dispelling Sliver': "Dispelling Sliver attempts to counteract one spell on a creature Aspera damages, as a rank-8 Dispel Magic. Against an enemy spellcaster protected by its own spells, it can remove the most important of them without an action. It takes the place of Aspera's spellheart, so it is for a planned fight against a known spellcaster.",
'Wolf Fang': "Wolf Fang deals damage equal to Cyrus's Strength modifier when he succeeds at a Trip. It is an inexpensive bonus at low level, but it takes the armour's attachment slot from more important talismans.",
'Phoenix Flask': "Phoenix Flask gives a 40-foot fly Speed for a minute, and the first time Cyrus flies in each round he deals fire damage to the creatures around him. It amounts to a Potion of Flying with damage added, and it fits in a moderate Potion Patch.",
'Potion of Flying (Standard)': "Potion of Flying gives a 40-foot fly Speed for a minute for one action. Against flying enemies, or where a fight takes place at several heights, it decides whether he can reach the enemy at all, and it fits in a Potion Patch.",
'Feather Step Stone': "Feather Step Stone lets Cyrus ignore difficult terrain for one turn as a free action when he Strides or Steps. That is useful against spells that create such terrain, but it occupies the armour's attachment slot.",
'Potion of Emergency Escape': "Potion of Emergency Escape makes Cyrus flee from every enemy with a large bonus to Speed. It gets him out of a fight that is lost, but the fleeing condition prevents him from helping his allies for the minute it lasts.",
'Runestone': "A runestone holds one rune that is not etched into an item. Cyrus needs one at 8, when Astral takes Aspera's only property slot, so that Fearsome can be kept on the runestone and returned to Aspera at 10 instead of being lost or bought again.",
'Glimmering Missive': "Glimmering Missive covers the creatures in a burst with glowing dust for an hour, so they cannot be concealed and invisible ones become easier to target. It takes two actions and free hands, so it is for an ambush that his side expects.",
"Lucky Rabbit's Foot": "Lucky Rabbit's Foot is an armour talisman. When Cyrus fails a Reflex save against a damaging effect, he rerolls it as a reaction, and if the second roll also fails he can Stride up to his Speed. Reflex is his lowest save, and the save this talisman rescues is usually against the area spell that hurts most. It shares the armour's attachment slot with the Mortalis Coin and any spellheart there, and at 175 gp each it is for fights in which area damage is expected.",
}
assert set(_CEV) <= set(C), set(_CEV) - set(C)
for _k, _v in _CEV.items():
    C[_k]['ev'] = _v
